-- certifications_security_reliability.sql
--
-- Why: the founder asked that every position be certified against the real certificate for its
-- craft and then examined. This file authors the question banks for the five security and
-- reliability certifications of the product_eng seats (it, security, qa_manager): CompTIA Linux+,
-- Google Professional Cloud DevOps Engineer, CISSP, CEH and ISTQB Advanced Level Test Manager.
-- 40 questions per bank at the real exam standard (scenario and application, not definitions),
-- four options, one key, a two-sentence rationale, the syllabus area named as the issuing body
-- names it, 10 of 40 marked 'hard', keys spread exactly ten per letter, never "all of the above".
-- The estate these seats run is Postgres plus Deno edge with row-level security, per-function
-- credentials, cron-driven jobs and CI gates that read production, so least privilege, secret
-- rotation, injection and access-control failure, incident response, observability and release
-- risk are deliberately over-represented.
--
-- role_certification rows and the exam sitter are authored by a sibling engineer; this file
-- touches public.certification_exam_question only.
--
-- Each bank is guarded by `where not exists (... certification = '<name>')` so the first author
-- of a shared bank wins and re-applying the file is a no-op.
--
-- Apply: node scripts/apply_sql.mjs scripts/sql/certifications_security_reliability.sql --apply --ddl

-- ============================ CompTIA Linux+ ============================
insert into public.certification_exam_question
  (certification, syllabus_area, difficulty, question, option_a, option_b, option_c, option_d, correct_option, rationale)
select * from (values
('CompTIA Linux+','1.0 System Management','exam','A root cron job writes nightly reports into /srv/reports, but members of the reports group cannot read the new files. Which single change makes every newly created file group-owned by reports and group-readable, without editing the job?','Set the setgid bit on /srv/reports and give the job a umask of 002','Run chmod 777 /srv/reports','Add root to the reports group','Set the sticky bit on /srv/reports','A','The setgid bit on a directory makes new entries inherit the directory group, and umask 002 leaves the group read bit intact. The sticky bit only restricts deletion, and 777 grants world access rather than fixing group ownership.'),
('CompTIA Linux+','1.0 System Management','exam','A service must start only after the local database is genuinely accepting connections, not merely after its unit has forked. Which configuration expresses that?','Restart=always on the consuming service','After= the database unit, with the database unit declared Type=notify so readiness is signalled','Requires= the database unit with Type=simple','WantedBy=multi-user.target on both units','B','After= fixes the ordering and Type=notify makes systemd wait for the daemon to signal readiness rather than for the fork to return. Requires= expresses a dependency but says nothing about ordering or readiness.'),
('CompTIA Linux+','1.0 System Management','hard','A filesystem reports 100% used by df, yet du of the same mount totals only a few gigabytes, and the figure keeps climbing while one application runs. What is the most likely cause?','Filesystem metadata corruption requiring fsck','A disk quota applied to the mount point','A deleted file is still held open by a running process','Inode exhaustion on the mount','C','Blocks are only reclaimed when the last descriptor to a deleted file is closed, so du, which walks names, and df, which counts blocks, disagree. lsof +L1 names the holder, and restarting or truncating it frees the space.'),
('CompTIA Linux+','1.0 System Management','exam','A new 500 GB disk must be added to an existing volume group and the reports logical volume grown online with its ext4 filesystem. Which order of operations is correct?','mkfs, mount, then vgextend','fdisk, resize2fs, then lvextend','lvcreate, pvcreate, then mkfs','pvcreate, vgextend, lvextend, then resize2fs','D','The disk must become a physical volume, join the volume group, and only then can the logical volume and finally the filesystem be grown. Growing ext4 before the underlying logical volume has room simply fails.'),
('CompTIA Linux+','1.0 System Management','exam','A host with 64 GB of RAM shows only 3 GB free but 40 GB in buff/cache, and no swap activity. What should the administrator conclude?','Memory is effectively available because page cache is reclaimable on demand','The host needs more RAM immediately','A memory leak is consuming the page cache','Swappiness must be raised to 100','A','Page cache is reclaimed under pressure, so the meaningful figure is the available column rather than free. No swap activity together with healthy available memory means the machine is behaving normally.'),
('CompTIA Linux+','1.0 System Management','hard','A daemon must be hard-limited to 2 GB of memory and killed if it exceeds that, durably across restarts. Which mechanism does this on a modern systemd host?','ulimit -v in the operator shell profile','MemoryMax= in the unit file, enforced through the cgroup v2 memory controller','nice -n 19 applied to the process','A cron job that greps ps output and kills the process','B','MemoryMax= applies a cgroup limit to every process in the unit and triggers the kernel out-of-memory killer at the boundary. A shell ulimit applies only to descendants of that shell and never governs a systemd-started service.'),
('CompTIA Linux+','1.0 System Management','exam','After a disk replacement the machine boots to an emergency shell because a UUID in /etc/fstab no longer resolves. Which repair is both correct and durable?','Remove the entry from fstab entirely','Add nofail to every entry in fstab','Remount root read-write, correct the entry to the UUID reported by blkid, then run systemctl daemon-reload','Boot permanently with init=/bin/bash','C','The device identifier changed, so the durable fix is to record the real UUID and reload the generated mount units. Deleting the entry or masking the failure with nofail leaves the filesystem unmounted at every boot.'),
('CompTIA Linux+','1.0 System Management','exam','A journald flood from one noisy unit is evicting entries an incident review still needs. Which configuration preserves the historical record?','Set Storage=volatile in journald.conf','Disable rsyslog so only journald writes','Run journalctl --vacuum-time=1h on a timer','Set Storage=persistent and raise SystemMaxUse to a larger on-disk cap','D','Persistent storage with a larger cap keeps entries across the flood and across reboots. Volatile storage and aggressive vacuuming actively discard exactly the history the reviewer needs.'),
('CompTIA Linux+','1.0 System Management','hard','A job must run every weekday at 02:15 Dubai time on a host whose clock is UTC. Which crontab entry is correct?','15 22 * * 0-4','15 2 * * 1-5','15 22 * * 1-5','15 6 * * 1-5','A','Dubai is UTC+4, so 02:15 local is 22:15 UTC on the previous calendar day, which shifts the weekday field back to Sunday through Thursday. Leaving 1-5 in place would skip Monday morning locally and fire on Saturday morning instead.'),
('CompTIA Linux+','1.0 System Management','exam','One package must be frozen on a production Debian-family host while every other package continues to receive updates. Which action does that?','Remove the repository from sources.list','apt-mark hold on that package','apt remove followed by reinstalling the old version','Delete the package cache','B','apt-mark hold records that the package must not be upgraded or automatically removed while other packages update normally. Removing the repository stops all updates from it, which is far broader than the requirement.'),
('CompTIA Linux+','1.0 System Management','exam','An operator needs the mount options the kernel is actually applying to /var, not the options fstab requests. Which command shows them?','cat /etc/fstab','lsblk -f','findmnt /var','du -sh /var','C','findmnt reports the live mount table including every option currently in force. fstab records intent, which can differ after a remount or a unit override.'),
('CompTIA Linux+','1.0 System Management','hard','Application logs must rotate daily, be kept fourteen days compressed, and the writing daemon must reopen its file after each rotation. Which logrotate stanza fits?','hourly with rotate 14 and copytruncate only','weekly with rotate 2 and nocompress','size 1G with rotate 14 and delaycompress only','daily with rotate 14, compress, and a postrotate hook that signals the daemon to reopen its log','D','Daily rotation with fourteen generations and compression meets the retention requirement, and the postrotate signal makes the daemon write to the new file. Without that signal the daemon keeps writing into the renamed inode and the new file stays empty.'),
('CompTIA Linux+','1.0 System Management','exam','A unit must be made impossible to start, whether manually or as a dependency of another unit, until further notice. Which command does that?','systemctl mask on the unit','systemctl disable on the unit','systemctl stop on the unit','Renaming the unit file','A','Masking links the unit to /dev/null so every start attempt, including a dependency-driven one, fails. Disabling only removes the boot-time symlink and still permits a manual or dependency start.'),
('CompTIA Linux+','1.0 System Management','exam','A cron job is replaced by a systemd timer, and a run missed while the host was powered off must still execute at the next boot. Which timer setting expresses that?','AccuracySec=1us','Persistent=true on the timer, with OnCalendar for the schedule','RemainAfterExit=yes on the service','WakeSystem=true','B','Persistent=true records the last trigger on disk and runs the unit immediately after boot when a scheduled point was missed. Accuracy and wake settings tune timing and suspend behaviour rather than catch-up.'),
('CompTIA Linux+','2.0 Security','hard','SELinux is enforcing and a web daemon is refused when reading content on a newly mounted volume, although the discretionary permissions are correct. Which action fixes it without weakening the control?','Run setenforce 0 at boot','chmod -R 777 on the volume','Record the correct context with semanage fcontext, then relabel the path with restorecon','Add the daemon account to the wheel group','C','The denial is a label mismatch, so recording the context rule and relabelling restores access while enforcement stays on. Disabling SELinux or widening the file mode removes the control instead of correcting the label.'),
('CompTIA Linux+','2.0 Security','exam','A deployment key must let an automation account run exactly one command over SSH and nothing else, enforced by the server. Which approach does that?','Give the account a login shell of /bin/bash and trust the client to send the right command','Set PermitRootLogin without-password','Distribute the same private key to every runner','Prefix the key in authorized_keys with command= plus no-pty, no-port-forwarding and no-agent-forwarding','D','A forced command makes the server ignore whatever the client requests and run only the fixed command, and the restrictions close the escape routes. Client-side discipline is not enforcement, because the client chooses what it sends.'),
('CompTIA Linux+','2.0 Security','exam','A credential file must be readable only by its service account and never by other local users on a host with several administrators. Which combination is correct?','Mode 0600 owned by the service account, inside a parent directory of mode 0750 owned by that account','Mode 0644 owned by root','Mode 0666 with SELinux enforcing','Mode 0640 with the file world-executable','A','Mode 0600 restricts the file to its owner and a 0750 parent stops other users traversing to it at all. Group and world read bits defeat the requirement whatever the mandatory access control layer does.'),
('CompTIA Linux+','2.0 Security','hard','An API token was committed to a repository and removed in a later commit. Which response is complete?','Delete the file in a new commit and move on','Revoke and reissue the token at the issuer first, then purge the object from history','Make the repository private','Add the path to .gitignore','B','Anything published must be treated as compromised, so the credential is invalidated at the issuer before anything else and only then is history rewritten. Later commits, visibility changes and ignore rules do nothing to a secret that has already been read.'),
('CompTIA Linux+','2.0 Security','exam','An auditor asks which local accounts can become root without being prompted for a password. Where is that answered authoritatively?','The shell fields in /etc/passwd','The output of who','The NOPASSWD rules in /etc/sudoers and /etc/sudoers.d','The hashes in /etc/shadow','C','Password-free escalation is granted only by NOPASSWD rules in the sudoers file and its drop-in directory. The passwd and shadow files describe accounts and hashes, not escalation policy.'),
('CompTIA Linux+','2.0 Security','exam','SSH must be accepted only from the office range and refused from every other source, using firewalld. Which construct expresses that?','Set the default zone to trusted','Add port 22 to the public zone','Stop firewalld and use hosts.deny','A rich rule accepting the ssh service from the office source range, with the blanket ssh service removed from the zone','D','A rich rule scopes the allowance to a source network while removing the unconditional service opening. Simply adding the port opens it to every source the zone already accepts.'),
('CompTIA Linux+','2.0 Security','hard','A certificate renewal automation must be able to prove that the private key never leaves the host it protects. Which design satisfies that claim?','Generate the key on the host and submit only a certificate signing request','Generate the key centrally and copy it out over scp','Store the key in the configuration repository, encrypted','Email the key to the certificate authority','A','A signing request carries only the public key and the identity, so issuance never requires the private key to move. Any design that transmits or stores the key elsewhere breaks the very property being claimed.'),
('CompTIA Linux+','2.0 Security','exam','A service account must own files and run a daemon but must never be usable interactively. How is that configured?','Delete the account and run the daemon as root','Set the account shell to /usr/sbin/nologin and lock the password','Set a long random password and record it in the wiki','Add the account to the sudo group without a password','B','A nologin shell together with a locked password removes interactive use while file ownership and service execution continue to work. Running as root or granting sudo enlarges the blast radius instead of reducing it.'),
('CompTIA Linux+','2.0 Security','exam','Configuration under /etc must be detectably unchanged between releases, and the evidence must survive a host compromise. Which approach addresses that?','rsync in delete mode against a peer','tmpwatch on a schedule','A file integrity tool such as AIDE, with the baseline database stored off the host','A nightly tar of /etc written into /tmp','C','Cryptographic baselines detect modification, and holding the database off the host prevents an intruder editing the evidence alongside the file. Copies and cleanup jobs never detect a change at all.'),
('CompTIA Linux+','2.0 Security','hard','A colleague must be able to restart exactly one service and read that service log, and nothing else. Which is the least privilege implementation?','Add the colleague to the wheel group','Share the root password for the maintenance window','Set the setuid bit on systemctl','A sudoers rule permitting only systemctl restart of that unit and journalctl -u for that unit','D','Command-scoped sudo rules grant precisely the two operations required and leave every other command denied. Group membership, a shared root password and a setuid binary all grant far more than was asked for.'),
('CompTIA Linux+','2.0 Security','exam','Repeated failed local logins must lock an account temporarily without an administrator intervening. Which mechanism provides that?','pam_faillock with a deny count and an unlock interval','Setting a shorter password expiry','Disabling password authentication in sshd','Reducing the TMOUT variable','A','pam_faillock counts consecutive failures and denies further attempts for a configured interval before releasing automatically. Expiry, key-only SSH and shell timeouts address different risks and do not throttle failed attempts.'),
('CompTIA Linux+','2.0 Security','exam','SSH must accept public keys only, with passwords refused even for accounts that have one. Which sshd configuration expresses that?','UsePAM no','PasswordAuthentication no together with PubkeyAuthentication yes, and KbdInteractiveAuthentication no','PermitEmptyPasswords no','MaxAuthTries 1','B','Refusing password authentication and the keyboard-interactive path leaves the public key method as the only way in. The other settings tighten related behaviour but still leave a password path available.'),
('CompTIA Linux+','3.0 Scripting, Containers, and Automation','hard','A container image must carry no build-time secret in any layer, yet the build needs a token to fetch a private dependency. Which approach meets that?','ARG TOKEN followed by a RUN that uses it','ENV TOKEN set near the top of the Dockerfile','A BuildKit secret mount, so the value exists only during that RUN and is never committed to a layer','COPY the token in and delete it in a later layer','C','A secret mount exposes the value to a single build step without persisting it in the resulting layer. Build arguments, environment variables and copy-then-delete all leave the value recoverable from image history or an earlier layer.'),
('CompTIA Linux+','3.0 Scripting, Containers, and Automation','exam','A shell script must stop at the first failing command, reject unset variables and fail when any stage of a pipeline fails. Which line does all three?','set -e','set -u','trap ERR','set -euo pipefail','D','set -e stops on error, -u rejects unset variables and -o pipefail propagates a failure from any pipeline stage. Any one of them alone leaves one of the three failure modes silent.'),
('CompTIA Linux+','3.0 Scripting, Containers, and Automation','exam','A backup script iterates over filenames that may contain spaces or newlines. Which loop is safe?','while IFS= read -r -d "" f; do ... done < <(find . -print0)','for f in $(ls); do','for f in `ls -1`; do','for f in *; do echo $f; done','A','Reading NUL-delimited names with read -r and an empty IFS preserves every character a filename may legally contain. Word splitting the output of ls breaks on spaces, newlines and glob characters.'),
('CompTIA Linux+','3.0 Scripting, Containers, and Automation','hard','A script reads a value from an untrusted file and passes it to an external program. Which practice removes command injection risk?','Escape semicolons and ampersands in the value','Execute the program directly with the value as a separate quoted argument, so no shell ever parses it','Run the command as a different user','Use eval with the arguments quoted','B','Passing the value as a distinct argument to an exec means no shell interprets it, so metacharacters carry no meaning at all. Escaping is an incomplete denylist and eval reintroduces exactly the shell parsing being avoided.'),
('CompTIA Linux+','3.0 Scripting, Containers, and Automation','exam','A container writes application data that must survive an image upgrade. Which storage choice is correct?','Write into the container filesystem and commit the container','Store the data in an environment variable','Mount a named volume at the data path','Rely on the container restart policy','C','A named volume lives outside the container lifecycle, so replacing the image leaves the data untouched. The writable container layer is discarded whenever the container itself is replaced.'),
('CompTIA Linux+','3.0 Scripting, Containers, and Automation','exam','A container must run as a non-root user with no route to regain privilege. Which combination expresses that?','--privileged with a non-root USER','Running as root but with a read-only root filesystem','Setting HOME to a non-root path','USER in the image, plus no-new-privileges and dropped Linux capabilities at run time','D','A non-root runtime user, the no-new-privileges flag and dropped capabilities together remove both the starting privilege and the escalation routes. A privileged container overrides the isolation completely.'),
('CompTIA Linux+','3.0 Scripting, Containers, and Automation','exam','An automation run must leave a file present with fixed content and ownership, and report changed only when it genuinely differed. Which approach is correct?','A declarative module that manages the file state and reports changed only on divergence','A script that appends the content on every run','A cron job that recreates the file hourly','A documented manual edit','A','Declarative state management compares desired against current state and acts only on a difference, which is what idempotence means. Appending or recreating on every run mutates the host each time and destroys the changed signal.'),
('CompTIA Linux+','3.0 Scripting, Containers, and Automation','exam','A script creates a working directory that must be removed even if the script exits on an error or a signal. Which construction guarantees that?','rm -rf at the end of the script','mktemp -d assigned to a variable, with a trap on EXIT that removes it','Writing into /tmp and relying on the tmpfiles cleaner','Creating the directory under the current working directory','B','A trap on EXIT runs on normal completion, on an error exit and on a caught signal, so the temporary tree is always removed. A final rm line is skipped whenever the script exits early.'),
('CompTIA Linux+','4.0 Troubleshooting','exam','A web service is unreachable from other hosts, yet curl to localhost on the same port succeeds. What should be checked first?','The application logs for a stack trace','Disk space on the root filesystem','Whether the daemon is bound to 127.0.0.1 rather than a routable address, and whether the firewall admits the port','Time synchronisation on the host','C','A working loopback request alongside a failing remote request points at bind scope or packet filtering, not application logic. ss -ltnp shows the bind address and the firewall rules show whether the port is admitted.'),
('CompTIA Linux+','4.0 Troubleshooting','exam','Latency on a database host has risen sharply. vmstat shows a high wa column, iostat shows device utilisation near 100% with a long queue, and CPU idle is high. Where is the bottleneck?','CPU saturation','Memory exhaustion','Network packet loss','Storage input and output saturation','D','High I/O wait with a saturated device and a growing queue while the CPU is idle is the signature of a storage bottleneck. CPU or memory pressure would instead show as low idle time or swapping.'),
('CompTIA Linux+','4.0 Troubleshooting','exam','A service logs a too many open files error while the system-wide file maximum is nowhere near reached. Where is the limit being hit?','The per-process descriptor limit, set by LimitNOFILE for the unit','The inode count of the filesystem','The kernel page cache size','The number of CPU cores','A','Per-process descriptor limits are enforced independently of the system-wide maximum, so one service can exhaust its own ceiling on an otherwise idle host. For a systemd unit the durable fix is LimitNOFILE in the unit file.'),
('CompTIA Linux+','4.0 Troubleshooting','exam','One internal domain fails to resolve while public names resolve normally. Which diagnostic isolates the cause fastest?','Ping the default gateway','Query the configured resolver with dig, then query the internal authoritative server directly and compare','Restart the network manager','Flush the ARP cache','B','Comparing the resolver answer with the authoritative answer immediately separates a forwarding or caching fault from a zone fault. Link-level checks cannot distinguish those cases at all.'),
('CompTIA Linux+','4.0 Troubleshooting','exam','A unit enters a restart loop immediately after a configuration change. Which sequence gives the cause with the least noise?','dmesg piped to tail','top sorted by CPU','systemctl status for that unit, then journalctl -u for that unit bounded to the change window','ls -l on the service binary','C','The unit status gives the exit code and the scoped journal query returns only that unit output around the change. The kernel ring buffer and process listings are not scoped to the failing unit.'),
('CompTIA Linux+','4.0 Troubleshooting','hard','Two nodes of a cluster both believe they are leader and both act, shortly after one of them experienced a long pause. Which condition most likely contributed?','A full disk on one node','A mismatched hostname','An expired TLS certificate on the peer link','Clock skew combined with a lease timeout shorter than the observed pause','D','Leases expire against a clock, so skew or a pause longer than the lease lets the second node conclude the first is gone while it is still running. Disk, naming and certificate faults produce outright failure rather than two simultaneous leaders.')
) as v(certification, syllabus_area, difficulty, question, option_a, option_b, option_c, option_d, correct_option, rationale)
where not exists (select 1 from public.certification_exam_question where certification = 'CompTIA Linux+');

-- ============ Google Professional Cloud DevOps Engineer ============
insert into public.certification_exam_question
  (certification, syllabus_area, difficulty, question, option_a, option_b, option_c, option_d, correct_option, rationale)
select * from (values
('Google Professional Cloud DevOps Engineer','Bootstrapping a Google Cloud organization for DevOps','exam','Every deployment pipeline currently authenticates with a long-lived downloaded service account key. Which change removes the key while keeping the pipeline able to deploy?','Adopt workload identity federation so the pipeline exchanges its own workload token for short-lived credentials','Rotate the key every thirty days','Store the key in a secret manager and inject it at run time','Grant the key the Owner role so it never needs replacing','A','Workload identity federation lets an external pipeline present its own attested identity and receive a short-lived access token, so no key exists to leak. Rotation and secret storage still leave a long-lived credential that can be exfiltrated between rotations.'),
('Google Professional Cloud DevOps Engineer','Bootstrapping a Google Cloud organization for DevOps','exam','A team must be able to deploy to the staging project but only read production. Which structure expresses that with least privilege?','Grant the team Editor at the organization node','Separate projects for staging and production, with the deploy role bound in staging and a viewer role bound in production','Give every engineer Owner on both projects and rely on audit logs','Use one project and separate the environments by resource naming','B','Environment separation by project makes the permission boundary a real boundary and lets each role binding be scoped to one environment. Naming conventions and organization-wide roles grant production write access to anyone who can deploy to staging.'),
('Google Professional Cloud DevOps Engineer','Bootstrapping a Google Cloud organization for DevOps','hard','An incident review found that a broad role was granted for one emergency and never removed. Which control prevents the recurrence structurally?','A quarterly manual access review','A policy that all grants go through code review','Time-bound conditional role bindings that expire automatically, with break-glass access logged and alerted','A written rule that emergency grants must be revoked','C','An expiry condition on the binding removes the privilege without anyone remembering to act, which is the failure mode being addressed. Reviews and written rules depend on the same human step that already failed once.'),
('Google Professional Cloud DevOps Engineer','Bootstrapping a Google Cloud organization for DevOps','exam','Infrastructure must be reproducible and every change reviewable before it reaches production. Which practice delivers that?','Document the console steps in a runbook','Snapshot the project after each change','Let each engineer apply changes from a local workstation','Declare the infrastructure as code in version control, applied only by a pipeline from the reviewed main branch','D','Declarative infrastructure in version control makes the change reviewable as a diff and the applied state reproducible from the repository. Console steps and local applies leave no reviewable artefact and drift immediately.'),
('Google Professional Cloud DevOps Engineer','Applying site reliability engineering practices to services','exam','A service has a 99.9% availability SLO over 30 days and has already consumed 90% of its error budget by day ten. What does SRE practice prescribe?','Freeze risky feature releases and spend the remaining capacity on reliability work until the budget recovers','Raise the SLO to 99.99% so the budget is larger','Continue releasing because the SLO has not yet been breached','Stop measuring until the window resets','A','The error budget is the agreed licence to take release risk, and exhausting it early is the signal to shift effort from features to reliability. Raising the target makes the budget smaller rather than larger, and ignoring the signal is what the budget exists to prevent.'),
('Google Professional Cloud DevOps Engineer','Applying site reliability engineering practices to services','exam','Which pair is a well-formed SLI and SLO for a request-driven API?','Average CPU utilisation below 70%','The proportion of requests returning a non-5xx status within 300 ms, targeted at 99.5% over a rolling 28 days','Zero incidents per quarter','Mean response time under one second','B','A good SLI is a ratio of good events to valid events measured at the user boundary, and the SLO adds a target and a window. Resource utilisation is a cause rather than user experience, and an average hides the tail that users actually feel.'),
('Google Professional Cloud DevOps Engineer','Applying site reliability engineering practices to services','hard','A burn-rate alert must page for an outage that would exhaust a 30-day budget in about two days, without paging for brief blips. Which configuration fits?','A single threshold on the instantaneous error ratio','An alert whenever any error is observed','A multiwindow burn-rate alert requiring a high burn rate over a long window and confirmed by a short window','A daily digest of yesterday error counts','C','Requiring the burn rate to hold over a long window suppresses blips, while the short window confirms the condition is still current before paging. A raw error threshold pages on noise and a digest arrives far too late to act on.'),
('Google Professional Cloud DevOps Engineer','Applying site reliability engineering practices to services','exam','Which item is legitimate toil to automate away, by the SRE definition?','Designing a new schema for an upcoming feature','Writing the postmortem for a major incident','Deciding the reliability targets with the product owner','Manually rerunning the same failed nightly job and re-checking the same three dashboards every morning','D','Toil is manual, repetitive, automatable work that scales with service size and carries no enduring value. Design, target setting and postmortem authorship are judgement work that produces lasting artefacts.'),
('Google Professional Cloud DevOps Engineer','Applying site reliability engineering practices to services','hard','A postmortem names an on-call engineer as the cause of an outage. What is wrong with it?','Nothing, accountability matters','It is blameless only in name; naming a person stops the review finding the system conditions that allowed the action to cause harm','Postmortems should not be written for single-service outages','It should also name the reviewer','B','A blameless postmortem asks which system properties let a reasonable action produce an outage, because those properties are what can be fixed. Attributing the outage to a person ends the investigation exactly where the useful findings begin.'),
('Google Professional Cloud DevOps Engineer','Applying site reliability engineering practices to services','exam','A downstream dependency intermittently times out and every client retries immediately, deepening the outage. Which client change is correct?','Retry twice as fast to clear the backlog','Exponential backoff with jitter, a retry budget, and a circuit breaker that sheds load when the dependency is failing','Remove all retries','Increase the client timeout to five minutes','B','Backoff with jitter spreads the retry storm, a budget caps amplification and a breaker stops sending traffic that cannot succeed. Faster retries and longer timeouts both increase the load on an already failing dependency.'),
('Google Professional Cloud DevOps Engineer','Implementing service monitoring strategies','exam','A latency SLI is reported as a mean and the service looks healthy, yet users complain. Which measurement change surfaces the problem?','Report a distribution and alert on high percentiles such as the 95th and 99th','Sample one request per minute','Report the median only','Alert on the maximum single request','A','Percentiles expose the tail that a mean conceals, and the tail is where user-visible slowness lives. Sparse sampling and single maxima are either blind to the tail or dominated by one outlier.'),
('Google Professional Cloud DevOps Engineer','Implementing service monitoring strategies','exam','Which set is the four golden signals of monitoring?','CPU, memory, disk and network','Latency, traffic, errors and saturation','Uptime, cost, headcount and deploys','Requests, threads, sockets and locks','B','The golden signals describe the service from the user perspective plus how close it is to its limit. Machine resource counters are useful diagnostics but do not describe user-visible behaviour.'),
('Google Professional Cloud DevOps Engineer','Implementing service monitoring strategies','hard','A rare failure affects one tenant, and per-request logs are too voluminous to keep in full. Which observability approach finds the cause?','Increase the log retention period tenfold','Alert on aggregate error rate only','Distributed tracing with tail-based sampling that keeps every failed or slow trace, correlated by a request identifier carried across services','Take a heap dump on every request','C','Tail-based sampling decides after the fact, so the rare failing traces are retained while the bulk of successful traffic is discarded. Aggregate alerting cannot isolate one tenant and blanket retention or dumps do not scale.'),
('Google Professional Cloud DevOps Engineer','Implementing service monitoring strategies','exam','Alerts must page only when a human must act immediately. Which alert violates that rule?','A page when the availability burn rate threatens the monthly budget','A page when a queue is growing without bound and will overflow within the hour','A page when the checkout error ratio exceeds the SLO threshold','A page for every failed single request and every node restart in an autoscaled pool','D','Symptom-based alerts tied to user impact are actionable, whereas individual request failures and routine instance churn are expected and require no action. Paging on them produces fatigue that makes the real pages less likely to be answered.'),
('Google Professional Cloud DevOps Engineer','Implementing service monitoring strategies','hard','A dashboard shows a metric at zero and the on-call declares the system healthy. What is the flaw?','Zero always means healthy','Nothing, provided the dashboard refreshes','The dashboard should use a bar chart','A zero can mean the guarded condition never occurred or that the instrument stopped reporting, so the metric needs a freshness or heartbeat signal alongside it','D','Absence of data and absence of the event look identical on the same axis, so a zero is not evidence of health on its own. Pairing the metric with a heartbeat or last-reported timestamp separates the two cases.'),
('Google Professional Cloud DevOps Engineer','Implementing service monitoring strategies','exam','Logs must be usable for post-incident querying across many services. Which practice matters most?','Structured logs with a consistent schema, a trace identifier on every entry, and severity used correctly','Log everything at debug level in production','Write logs only to the local disk of each instance','Use a different field name per service for the request identifier','A','A consistent structure with a correlating identifier is what makes a cross-service query possible at all, and correct severity keeps the signal usable. Debug-level firehoses, local-only storage and inconsistent field names each make correlation impossible.'),
('Google Professional Cloud DevOps Engineer','Optimizing service performance','exam','A service is CPU-bound at peak and autoscaling reacts too slowly, causing dropped requests. Which change addresses the cause?','Add more log statements to diagnose it during the next peak','Raise the instance size only','Tune the autoscaler on a leading signal such as queue depth or request concurrency, and keep enough headroom for the observed scale-up time','Increase the client timeout','C','Scaling on a signal that leads saturation, with headroom sized to the time it takes to add capacity, means capacity arrives before the queue overflows. A bigger instance or a longer timeout does not change the reaction time that caused the drops.'),
('Google Professional Cloud DevOps Engineer','Optimizing service performance','exam','A daily batch job and the interactive API share one database and the API slows every night. Which remedy is most appropriate?','Ask users not to work at night','Isolate the workloads, for example by running the batch against a read replica and rate-limiting its work, so the interactive path keeps its capacity','Increase the API timeout','Add an index to every table','B','Separating the noisy neighbour onto its own capacity restores the interactive path without depending on the batch being small. Timeouts and blanket indexing do not stop the batch consuming the shared resource.'),
('Google Professional Cloud DevOps Engineer','Optimizing service performance','hard','Profiling shows a service spends most of its wall time waiting on many small sequential calls to one dependency. Which optimisation gives the largest gain?','Move to faster instances','Increase the thread pool size','Batch or pipeline the calls and cache the stable results, so the number of round trips falls','Compress the response payloads','C','When latency is dominated by round trips, removing round trips is the only change that attacks the dominant term. Faster CPUs, more threads and smaller payloads do not reduce the number of sequential waits.'),
('Google Professional Cloud DevOps Engineer','Optimizing service performance','exam','A cost review shows a large spend on an over-provisioned cluster that must be reduced without risking the SLO. What is the disciplined approach?','Halve the fleet immediately and watch for complaints','Do nothing, because reliability always outranks cost','Move to the cheapest machine family available','Reduce capacity in steps, verifying the SLI and the saturation signal at each step, and stop while headroom remains for the observed peak','D','Stepwise reduction with the reliability indicator watched at each step converts a guess into a measurement, and stopping while headroom remains preserves the budget. An immediate halving tests the change on live users.'),
('Google Professional Cloud DevOps Engineer','Building and implementing CI/CD pipelines for a service','exam','A release must be verifiable as built from reviewed source and unmodified afterwards. Which practice provides that?','Tag the release in the issue tracker','Build only on the developer workstation that owns the service','Build in a hermetic pipeline from the reviewed commit, record provenance, and sign the artefact so the deployer verifies the signature','Rely on the container registry being private','C','Provenance plus a signature lets the deploying system verify what was built and from where, which is what the requirement asks. Privacy of the registry says nothing about how an image inside it was produced.'),
('Google Professional Cloud DevOps Engineer','Building and implementing CI/CD pipelines for a service','exam','A risky change must reach 1% of traffic first, with an automatic rollback if the error SLI degrades. Which strategy is described?','Blue-green deployment','A canary release with automated analysis of the canary SLI against the baseline','A rolling restart','Recreate deployment','B','A canary sends a small slice of live traffic to the new version and compares its indicators with the baseline before proceeding. Blue-green switches all traffic at once and a rolling restart has no comparison step.'),
('Google Professional Cloud DevOps Engineer','Building and implementing CI/CD pipelines for a service','hard','A database migration must ship with a service change that cannot be rolled back cleanly if the old code meets the new schema. Which sequence is safe?','Deploy the migration and the code together in one step','Roll back the migration if the deploy fails','Expand the schema in a backward-compatible step, deploy the code that tolerates both shapes, then contract the schema in a later release','Take the service down for the migration window','C','Expand, migrate, contract keeps every intermediate state readable by both the old and the new code, so either version can run during the rollout. A combined step makes rollback impossible the moment the old code meets the new schema.'),
('Google Professional Cloud DevOps Engineer','Building and implementing CI/CD pipelines for a service','hard','A pipeline gate reads production to prove a property, and it passes on an empty result set. What is wrong with the gate?','Nothing, an empty result means no violations','It should run more often','Reading production from CI is always invalid','A count of zero cannot distinguish a system with no violations from an instrument that measured nothing, so the gate must first assert the population it examined is non-empty','D','A zero is only evidence when the query is known to have looked at something, which requires asserting the denominator. Otherwise a broken query, a renamed column or an empty window turns into a green check.'),
('Google Professional Cloud DevOps Engineer','Building and implementing CI/CD pipelines for a service','exam','Deployment credentials must not be readable by anyone who can read the pipeline definition. Which arrangement achieves that?','Store them as plaintext variables in the pipeline file','Print them to the build log for debugging','Commit them encrypted with a key stored beside them','Keep them in a secret manager, granted to the pipeline identity at run time and never echoed to the build log','D','A secret manager keeps the value out of the repository and scopes access to the running identity, so reading the definition reveals only a reference. A key committed next to its ciphertext protects nothing.'),
('Google Professional Cloud DevOps Engineer','Building and implementing CI/CD pipelines for a service','exam','A flaky integration test is rerun until it passes so the pipeline stays green. What is the consequence?','The pipeline is now correctly configured','Reruns make the test faster over time','The signal is destroyed: a real regression that fails intermittently will also be retried into a pass, so the test must be fixed or quarantined','Flakiness only affects local runs','C','Retrying until green converts every intermittent failure, real or not, into a pass and therefore removes the ability to detect a class of regression. The correct response is to fix the flakiness or quarantine the test so its result stops being trusted.'),
('Google Professional Cloud DevOps Engineer','Building and implementing CI/CD pipelines for a service','hard','A rollback of the previous release took forty minutes because the artefact had to be rebuilt. Which change reduces recovery time most?','Add more reviewers to each release','Write a longer rollback runbook','Keep immutable, versioned artefacts so rollback is a redeploy of a known-good version, and rehearse it','Deploy less often','C','If the previous artefact still exists and is immutable, rolling back becomes a deployment rather than a build, which is the dominant cost. Documentation and slower release cadence do not shorten the mechanical recovery step.'),
('Google Professional Cloud DevOps Engineer','Building and implementing CI/CD pipelines for a service','exam','A feature must be shipped to production but revealed to users later, without a second deployment. Which technique fits?','A long-lived feature branch merged on launch day','A feature flag defaulting to off, with the rollout controlled independently of the deploy','A separate production project for the feature','A manual database toggle applied by an operator','B','A flag decouples release from deployment, so the code ships continuously and exposure is a runtime decision. A long-lived branch defers integration risk to the least convenient moment.'),
('Google Professional Cloud DevOps Engineer','Applying site reliability engineering practices to services','exam','An SLO is being agreed and the product owner proposes 100% availability. What is the correct response?','Accept it as an aspiration','Explain that a 100% target leaves no error budget, makes every change unjustifiable and ignores dependencies outside the service, so a target just above measured user need is chosen instead','Set it to 100% but exclude planned maintenance','Set no target at all','B','A perfect target removes the error budget that funds change and is unachievable given dependencies the service does not control. Targets are set just above the level at which users notice, which keeps both reliability and delivery viable.'),
('Google Professional Cloud DevOps Engineer','Applying site reliability engineering practices to services','hard','Which practice best converts an incident into durable improvement?','Close the incident once the service recovers','A blameless postmortem with a timeline, contributing conditions, and owned dated action items tracked to completion','Send a summary email to the team','Add the incident to a quarterly count','B','The improvement comes from the owned and tracked actions, not from the narrative, so the postmortem must end in commitments with owners and dates. Recovery alone leaves the conditions that produced the incident in place.'),
('Google Professional Cloud DevOps Engineer','Implementing service monitoring strategies','exam','A metric cardinality explosion has made queries slow and expensive after a label containing a user identifier was added. What is the correct remedy?','Increase the retention period','Remove the unbounded label from the metric and carry per-user detail in logs or traces instead','Sample the metric randomly','Add more storage','B','Metrics are aggregates and must carry bounded label sets, while per-entity detail belongs in logs and traces. Storage and sampling treat the symptom and leave the unbounded dimension in place.'),
('Google Professional Cloud DevOps Engineer','Optimizing service performance','exam','A cache was added and the hit rate is high, yet tail latency did not improve. What is the most likely explanation?','Caches never help tail latency','The slow requests are precisely the ones that miss the cache, so the tail is dominated by the uncached path','The cache should be larger','The metric is wrong','B','A high average hit rate can coexist with every slow request missing, because the tail is made of the unusual requests. Improving the tail means addressing the miss path or pre-populating for it.'),
('Google Professional Cloud DevOps Engineer','Bootstrapping a Google Cloud organization for DevOps','exam','An organization policy must prevent any project from creating a resource with a public address, including by future teams. Where is that enforced?','In a code review checklist','In each project README','As an organization policy constraint inherited by all projects in the hierarchy','By asking teams to self-certify quarterly','C','A constraint set at the organization node applies to every project beneath it, including projects created later, which is what the requirement asks. Checklists and self-certification depend on people remembering.'),
('Google Professional Cloud DevOps Engineer','Building and implementing CI/CD pipelines for a service','exam','A pipeline builds an image whose base layer includes a vulnerable library. Which control catches this before deployment?','A manual review of the Dockerfile','Automated vulnerability scanning of the built image in the pipeline, with a policy that blocks deployment above an agreed severity','Scanning the source repository only','Scanning production images monthly','B','Scanning the built artefact catches vulnerabilities introduced by base layers and transitive dependencies that source scanning cannot see, and a blocking policy stops the deploy. Monthly production scanning finds the problem only after it has shipped.'),
('Google Professional Cloud DevOps Engineer','Applying site reliability engineering practices to services','exam','On-call load has become unsustainable and engineers are burning out. Which SRE response is correct?','Add more people to the rotation and continue','Measure the pages, attack the top sources of pages and toil, and hand the service back to development if the reliability bar cannot be met','Silence the noisiest alerts','Extend shifts so handovers are rarer','B','SRE treats an unsustainable page load as a signal about the service, addressed by fixing the top page sources and, if that fails, returning operational responsibility. Adding people or silencing alerts hides the signal without changing the service.'),
('Google Professional Cloud DevOps Engineer','Implementing service monitoring strategies','exam','A scheduled job must be known to have run, not merely known to have not failed. Which monitoring pattern expresses that?','An alert on job error logs','A dashboard of job duration','Dead man switch monitoring, where the absence of a success heartbeat within the expected interval raises the alert','A weekly report of job counts','C','Alerting on the absence of an expected signal detects a job that never started, which an error-only alert cannot see. Duration charts and weekly reports show the runs that happened, not the ones that silently did not.'),
('Google Professional Cloud DevOps Engineer','Optimizing service performance','exam','Under overload the service currently fails every request slowly. Which behaviour is preferable and how is it achieved?','Fail everything faster by lowering all timeouts','Queue indefinitely so nothing is lost','Retry internally until success','Shed load early with admission control, so a bounded share of requests is served well rather than all requests served badly','D','Admission control preserves useful throughput for the requests it accepts instead of spreading failure across every request. Unbounded queues and internal retries convert overload into growing latency and amplification.'),
('Google Professional Cloud DevOps Engineer','Building and implementing CI/CD pipelines for a service','exam','A team wants confidence that a rollback path works before it is needed in an incident. What should they do?','Assume the previous artefact will deploy','Rehearse the rollback on a schedule against a production-like environment and record the measured time to recover','Write the rollback steps in the runbook only','Test the rollback only after the next incident','B','A rehearsed rollback with a measured recovery time is evidence, and rehearsal is what finds the missing permission or expired artefact. An untested path is an assumption, and incidents are the worst place to discover it fails.'),
('Google Professional Cloud DevOps Engineer','Bootstrapping a Google Cloud organization for DevOps','exam','Audit logs must be tamper-evident and readable by auditors who have no access to the workloads. Which arrangement fits?','Keep logs in each project with the workload team as administrators','Export audit logs to a separate, restricted sink with retention locked, and grant auditors read access only there','Email a monthly log summary to the auditors','Disable log deletion permissions for everyone including administrators of the sink','B','A separate restricted sink with locked retention separates the reader from the audited party and prevents deletion by the workload team. Leaving logs where the audited team administers them destroys the independence the control depends on.'),
('Google Professional Cloud DevOps Engineer','Applying site reliability engineering practices to services','exam','What is the correct relationship between an SLA and an SLO?','They are the same thing','The SLA is the internal target and the SLO the external contract','The SLO is the internal target and is set stricter than the externally promised SLA, so the team reacts before the contract is breached','SLOs apply only to paid customers','C','A stricter internal objective leaves room to detect and correct degradation before the contractual promise is broken. Setting them equal means the first alert coincides with the breach it was meant to prevent.')
) as v(certification, syllabus_area, difficulty, question, option_a, option_b, option_c, option_d, correct_option, rationale)
where not exists (select 1 from public.certification_exam_question where certification = 'Google Professional Cloud DevOps Engineer');

-- ==== CISSP (Certified Information Systems Security Professional) ====
insert into public.certification_exam_question
  (certification, syllabus_area, difficulty, question, option_a, option_b, option_c, option_d, correct_option, rationale)
select * from (values
('CISSP (Certified Information Systems Security Professional)','Domain 1: Security and Risk Management','exam','A quantitative risk assessment gives an asset value of AED 400,000, an exposure factor of 25% and an annual rate of occurrence of 0.5. A control costing AED 70,000 a year would reduce the rate to 0.1. What should the security manager recommend?','Reject the control, because the annualised loss is AED 50,000 and the control costs more than the AED 40,000 of loss it removes','Accept the control, because any risk reduction is worthwhile','Transfer the risk without calculating','Accept the control because the asset value exceeds the control cost','A','The single loss expectancy is AED 100,000 and the annualised loss expectancy falls from AED 50,000 to AED 10,000, a benefit of AED 40,000 against a cost of AED 70,000. A control that costs more than the loss it avoids is not justified on its own economics.'),
('CISSP (Certified Information Systems Security Professional)','Domain 1: Security and Risk Management','exam','Senior management formally decides to run a legacy system past its supported life rather than fund replacement. In risk terms, what has happened and what must accompany it?','The risk has been mitigated','The risk has been accepted, which requires documented sign-off by the accountable owner, a stated review date and compensating controls','The risk has been transferred to the vendor','The risk has been avoided','B','Choosing to bear a known risk is acceptance, and acceptance is only valid when the accountable owner records it with a review date. Without documented ownership the decision is not a control decision at all, it is drift.'),
('CISSP (Certified Information Systems Security Professional)','Domain 1: Security and Risk Management','hard','A UAE-based marketplace processes personal data of its suppliers and buyers. Under the federal personal data protection law, which practice best reflects the data minimisation principle?','Retain every field indefinitely in case it becomes useful','Collect all available fields but encrypt them','Collect only the personal data necessary for the stated purpose and delete it when that purpose ends','Publish a privacy notice covering all possible collection','C','Minimisation limits both what is collected and how long it is kept to what the declared purpose requires. Encryption and a broad notice protect or disclose data that should not have been collected in the first place.'),
('CISSP (Certified Information Systems Security Professional)','Domain 1: Security and Risk Management','exam','A due diligence review of a critical supplier must give assurance about the controls that protect the customer data it holds. Which evidence is strongest?','A completed self-assessment questionnaire','A marketing page describing their security posture','A statement that they use encryption','An independent audit report covering the relevant control objectives, with the exceptions and the scope read in full','D','Independent attestation with its scope and exceptions examined is evidence, because a narrow scope can make a clean report meaningless. Self-assessments and claims are assertions by the party being assessed.'),
('CISSP (Certified Information Systems Security Professional)','Domain 1: Security and Risk Management','exam','Which statement correctly distinguishes a policy from a standard and a procedure?','A policy is a step-by-step instruction','A policy states management intent and is mandatory, a standard fixes the specific mandatory implementation, and a procedure gives the ordered steps','A standard is advisory guidance','A procedure sets the organisational objective','B','The hierarchy runs from intent, through mandatory implementation choices, to executable steps. Confusing them produces policies nobody can follow and procedures that outlive the intent behind them.'),
('CISSP (Certified Information Systems Security Professional)','Domain 2: Asset Security','exam','Data classification has been introduced but nothing changed operationally. What is the missing step that gives classification effect?','Publishing the classification scheme','Mapping each classification to required handling: access, storage, transmission, retention and destruction, and enforcing it technically','Asking each team to guess their classification','Adding a label to document footers','B','A classification is only useful once it determines handling requirements that are actually enforced. A label with no attached obligation changes nothing about how the data is treated.'),
('CISSP (Certified Information Systems Security Professional)','Domain 2: Asset Security','exam','Solid-state drives holding confidential data are being retired and must be unrecoverable, while the drives themselves are to be resold. Which method is appropriate?','A single-pass overwrite with zeros','Deleting the partitions','Cryptographic erase of the drive-managed encryption key, verified, or physical destruction if resale is not required','A quick format','C','Wear levelling means an overwrite cannot be guaranteed to reach every physical cell, whereas destroying the media encryption key renders all remaining ciphertext useless. Deleting partitions or formatting removes only the index.'),
('CISSP (Certified Information Systems Security Professional)','Domain 2: Asset Security','hard','A production database is copied into a test environment so developers can reproduce a defect. Which control best preserves both usefulness and confidentiality?','Grant developers read-only production access instead','Copy the data unchanged into a restricted test project','Anonymise or tokenise the personal fields while preserving referential integrity and data shape, so the defect still reproduces','Encrypt the test database at rest','C','Removing the identifying content while keeping the structure lets the defect reproduce without exposing real people to a lower-assurance environment. Encryption at rest does not protect data from the developers who are authorised to query it.'),
('CISSP (Certified Information Systems Security Professional)','Domain 2: Asset Security','exam','Who decides the classification and permitted uses of a dataset, and who implements the protection?','The data custodian decides and the data owner implements','The data owner decides and the data custodian implements','The security officer does both','The end users decide collectively','B','Ownership carries accountability for value, classification and permitted use, while custody carries the operational duty to protect it as instructed. Merging the roles removes the separation that makes access decisions reviewable.'),
('CISSP (Certified Information Systems Security Professional)','Domain 2: Asset Security','exam','A retention schedule says records are kept seven years, but backups keep everything indefinitely. What is the risk and the correct response?','No risk, backups are separate','Extend the retention schedule to match the backups','Delete all backups','Data past its retention period remains discoverable and in scope for breach, so backup retention must be aligned to the schedule and expiry enforced','D','Data that should have been destroyed but persists in backups still carries legal and breach exposure. Aligning backup expiry to the retention schedule is what makes the schedule real.'),
('CISSP (Certified Information Systems Security Professional)','Domain 3: Security Architecture and Engineering','exam','A design places a firewall, host hardening, application authorisation checks and database row-level policies on the same access path. Which principle is being applied?','Defence in depth, so the failure of one layer does not by itself grant access','Security through obscurity','Separation of duties','Least common mechanism','A','Independent layered controls mean a single bypassed control still leaves the attacker outside the asset. The value lies in the layers failing independently rather than in their number.'),
('CISSP (Certified Information Systems Security Professional)','Domain 3: Security Architecture and Engineering','exam','A system must fail in a way that never grants access when its authorisation service is unreachable. Which design property is required?','Fail open for availability','Fail secure, so an indeterminate authorisation result is treated as a denial','Retry indefinitely until the service answers','Cache the last decision permanently','B','A fail-secure default converts an unknown answer into a denial, so an outage cannot become an authorisation bypass. Failing open and permanent caching both let unavailability grant access.'),
('CISSP (Certified Information Systems Security Professional)','Domain 3: Security Architecture and Engineering','hard','A team proposes to store passwords encrypted so they can be recovered for users who forget them. What is the objection?','Encryption is slower than hashing','Recoverability is fine if the key is protected','Passwords must be stored as salted, computationally expensive one-way hashes, because reversibility means a key compromise discloses every credential and defeats non-repudiation','Users rarely forget passwords','C','A verifier must only need to confirm a password, never to recover it, so a one-way hash with a per-user salt and a deliberate work factor is required. Any reversible scheme makes the key a single point that discloses every credential.'),
('CISSP (Certified Information Systems Security Professional)','Domain 3: Security Architecture and Engineering','exam','Which statement about TLS and data at rest is correct for a database holding regulated data?','TLS in transit removes the need for encryption at rest','Encryption at rest removes the need for TLS','They address different threats: TLS protects data on the wire and at-rest encryption protects the stored media, and both are needed with keys managed separately from the data','Both are optional if the network is private','C','Interception and media theft are distinct threats with distinct controls, and holding the keys with the data defeats the at-rest control. A private network is still a network and does not authenticate endpoints.'),
('CISSP (Certified Information Systems Security Professional)','Domain 3: Security Architecture and Engineering','exam','A hardware security module is proposed for signing keys. What is the primary security property it provides?','Faster cryptographic operations','Keys are generated and used inside a tamper-resistant boundary and cannot be exported in plaintext, so compromise of the host does not disclose the key','It removes the need for access control','It provides encryption at rest for the database','B','The value of the module is non-exportability, which breaks the link between host compromise and key compromise. Performance is a side benefit and access control is still required to authorise use.'),
('CISSP (Certified Information Systems Security Professional)','Domain 4: Communication and Network Security','exam','A flat internal network let an intrusion in one workstation reach the production database directly. Which architectural change addresses the cause?','Change the database password more often','Add antivirus to every workstation','Increase the firewall log retention','Segment the network so the database is reachable only from a defined application tier, with default-deny between segments','D','Segmentation with default-deny removes the lateral path that turned one compromised endpoint into a database breach. Endpoint hygiene and credential rotation do not remove the reachability that made the pivot possible.'),
('CISSP (Certified Information Systems Security Professional)','Domain 4: Communication and Network Security','exam','A zero trust design is being adopted. Which statement captures it correctly?','Trust is granted by network location once inside the perimeter','Every request is authenticated and authorised on its own merits, with device and identity signals evaluated per request regardless of network position','A VPN alone implements zero trust','Zero trust means no encryption is needed internally','B','Zero trust removes implicit trust from network position and makes each request prove itself. A VPN merely extends the perimeter, which is the assumption zero trust is discarding.'),
('CISSP (Certified Information Systems Security Professional)','Domain 4: Communication and Network Security','hard','An attacker on the same segment is able to read traffic between two hosts although a switch is in use. Which attack explains this and which control mitigates it?','A DNS cache poisoning attack, mitigated by DNSSEC','ARP cache poisoning, mitigated by dynamic ARP inspection with DHCP snooping and, decisively, by end-to-end encryption','A SYN flood, mitigated by SYN cookies','A smurf attack, mitigated by disabling directed broadcast','B','Poisoning the ARP caches redirects frames through the attacker even on a switched segment, and dynamic ARP inspection blocks the forged bindings. End-to-end encryption removes the value of interception even if the redirection succeeds.'),
('CISSP (Certified Information Systems Security Professional)','Domain 4: Communication and Network Security','exam','An outbound-only egress policy is proposed for a server subnet holding sensitive data. What is the primary benefit?','It speeds up the network','It restricts the paths available for exfiltration and command and control, so an intrusion cannot simply call out to an arbitrary destination','It removes the need for inbound rules','It replaces monitoring','B','Constraining egress to known destinations turns exfiltration and remote control into a visible policy violation rather than ordinary outbound traffic. It does not replace inbound filtering or monitoring.'),
('CISSP (Certified Information Systems Security Professional)','Domain 4: Communication and Network Security','exam','Which control most directly addresses the risk that an internal service is reached by a request forged by a compromised front end?','Longer session timeouts','Mutual TLS between services plus authorisation on the callee, so the caller identity is proven and its permissions are checked at the destination','A shared secret in a header','Rate limiting at the edge','B','Proving the caller identity cryptographically and enforcing authorisation at the destination means a forged or replayed call fails at the service that owns the data. Shared header secrets are bearer tokens that a compromised front end already holds.'),
('CISSP (Certified Information Systems Security Professional)','Domain 5: Identity and Access Management','exam','An employee has moved between three departments and retains the access from each. What is this and which control corrects it?','Privilege creep, corrected by periodic entitlement recertification and by role changes triggering removal of the prior role','Separation of duties, corrected by adding an approver','Least privilege, already satisfied','Mandatory access control, corrected by relabelling','A','Accumulated entitlements across role changes are privilege creep, and the fix is both a joiner-mover-leaver trigger and a recurring recertification. Adding approvers to new requests does nothing about access already held.'),
('CISSP (Certified Information Systems Security Professional)','Domain 5: Identity and Access Management','exam','Which combination constitutes genuine multi-factor authentication?','A password and a security question','A password and a hardware authenticator that proves possession of a private key','Two passwords of different lengths','A username and a password','B','Multi-factor requires factors of different kinds, here knowledge and possession, so compromising one does not yield the other. Security questions and second passwords are both knowledge and fall to the same attack.'),
('CISSP (Certified Information Systems Security Professional)','Domain 5: Identity and Access Management','hard','An access model must let a request be permitted only when the requester is in the owning department, during business hours, and from a managed device. Which model expresses this natively?','Discretionary access control','Role-based access control alone','Attribute-based access control, evaluating subject, resource, action and environment attributes in a policy','Mandatory access control by clearance label','C','Attribute-based policy evaluates contextual attributes such as time and device posture alongside subject and resource, which role membership alone cannot express. Encoding every context combination as a role produces a role explosion instead.'),
('CISSP (Certified Information Systems Security Professional)','Domain 5: Identity and Access Management','exam','A privileged administrative account must be usable for emergencies but never held continuously by an individual. Which arrangement fits?','Share the credential among the senior team','Assign it permanently to the most trusted administrator','Disable it entirely','Vault the credential with just-in-time checkout, approval, session recording and automatic rotation after use','D','Just-in-time issuance with approval and post-use rotation means no individual holds standing privilege and every use is attributable. A shared or permanently assigned credential destroys attribution and leaves the privilege always live.'),
('CISSP (Certified Information Systems Security Professional)','Domain 5: Identity and Access Management','exam','A federated login is implemented and the relying party must be sure an assertion was issued for it and is still current. What must it validate?','Only that the assertion is well-formed','Only the presence of a user identifier','The issuer, the signature, the audience restriction and the validity window, and it must reject a replayed assertion identifier','That the user has logged in before','C','An assertion is only meaningful when the issuer is trusted, the signature verifies, the audience names this relying party and the time window is current. Omitting the audience check lets an assertion minted for another service be replayed here.'),
('CISSP (Certified Information Systems Security Professional)','Domain 6: Security Assessment and Testing','exam','A vulnerability scan report and a penetration test report are proposed as interchangeable. What is the difference that matters?','They are equivalent','A scan enumerates known weaknesses broadly, while a penetration test attempts exploitation and chaining to demonstrate real business impact','A penetration test is automated and a scan is manual','A scan proves exploitability','B','Enumeration finds candidates, whereas exploitation and chaining demonstrate which candidates actually lead to impact. Treating a scan as proof of exploitability both overstates and understates the real risk.'),
('CISSP (Certified Information Systems Security Professional)','Domain 6: Security Assessment and Testing','exam','An access control audit must prove that no ordinary user can read another tenant rows. Which test design is sound?','Ask the developers whether the policy is enforced','Read the policy definition and confirm it exists','Review the code that builds the query','Authenticate as an ordinary user of tenant A and attempt to read tenant B rows through the production path, asserting the attempt is denied','D','Only an attempted access through the real path proves enforcement, because a policy can exist and still be bypassed by the code path in use. Reading definitions or asking the authors tests the intent rather than the behaviour.'),
('CISSP (Certified Information Systems Security Professional)','Domain 6: Security Assessment and Testing','hard','A control test returns zero findings. Before reporting the control effective, what must the assessor establish?','That the test ran without error','That the sample was large','That the test actually examined a non-empty population containing cases the control should act on, otherwise zero cannot distinguish an effective control from an inert test','That the owner agrees with the result','C','A count of zero is evidence only when the denominator is known to be non-empty and to include cases the control must catch. Otherwise a broken query, an empty window or a filtered population produces a false assurance.'),
('CISSP (Certified Information Systems Security Professional)','Domain 6: Security Assessment and Testing','exam','Log review must give assurance that privileged actions are attributable. Which finding would be the most serious?','Logs are retained for two years','Administrators share one account, so actions cannot be attributed to an individual','Logs are stored in a central system','Log volume grew this quarter','B','Shared privileged accounts destroy attribution, which is the property the review exists to confirm. Retention and centralisation are supporting characteristics, not the property under test.'),
('CISSP (Certified Information Systems Security Professional)','Domain 6: Security Assessment and Testing','exam','A code review process is being assessed for security value. Which characteristic matters most?','That every change is reviewed by anyone available','That reviews are timed','That security-relevant changes, such as authorisation and input handling, are identified and reviewed against a defined checklist by someone other than the author','That the reviewer count is high','C','Independent review focused on the code paths that decide access and handle untrusted input is where review finds security defects. Volume and timing say nothing about whether the risky paths were examined.'),
('CISSP (Certified Information Systems Security Professional)','Domain 7: Security Operations','exam','A likely compromise of a production server is detected. Which sequence follows accepted incident response practice?','Rebuild the server immediately to restore service','Detect and analyse, contain, eradicate, recover, then conduct lessons learned, preserving evidence throughout','Notify the press, then investigate','Eradicate first, then decide whether it was an incident','B','Containment before eradication limits spread while preserving the evidence that eradication would destroy, and the review closes the loop. Rebuilding first destroys the only record of how the intrusion happened.'),
('CISSP (Certified Information Systems Security Professional)','Domain 7: Security Operations','exam','Volatile evidence must be preserved on a suspected compromised host. In which order should it be collected?','Disk image first, then memory','Memory and running state first, then network connections, then disk, following the order of volatility','Logs first, then reboot the host','Reboot to a clean state and then image the disk','B','Data is collected from most volatile to least, because memory and connection state vanish on reboot while disk contents persist. Rebooting first destroys precisely the evidence that identifies the running intrusion.'),
('CISSP (Certified Information Systems Security Professional)','Domain 7: Security Operations','hard','A business continuity plan states a recovery time objective of four hours and a recovery point objective of fifteen minutes, but backups run nightly to tape stored off-site with a six-hour retrieval time. What is the correct conclusion?','The plan is met because backups exist','The objectives are unmet on both counts: nightly backups cannot deliver a fifteen-minute recovery point and six-hour retrieval cannot deliver a four-hour recovery time','Only the recovery point objective is unmet','Only the recovery time objective is unmet','B','A fifteen-minute recovery point requires replication or frequent log shipping, not a nightly copy, and a six-hour retrieval already exceeds the four-hour recovery time. Both objectives fail against the stated arrangement.'),
('CISSP (Certified Information Systems Security Professional)','Domain 7: Security Operations','exam','A change is applied directly to production during an incident. What must happen for the change control process to remain intact?','Nothing, incidents are exempt','The change is recorded retrospectively as an emergency change, reviewed and approved after the fact, and reconciled with the source of truth','The change is left undocumented to avoid alarm','The process is suspended for the quarter','B','Emergency change paths exist precisely so urgent action is possible and still ends up recorded, reviewed and reconciled. An unrecorded production change becomes undetectable drift and defeats every later comparison.'),
('CISSP (Certified Information Systems Security Professional)','Domain 7: Security Operations','exam','Which arrangement best detects a malicious insider with administrative rights?','Trusting the administrator role','Requiring the administrator to self-report anomalies','Independent, append-only logging outside the administrator control, with alerting on privileged actions and separation of duties for high-impact operations','Longer passwords for administrators','C','Detection requires evidence the subject cannot alter, plus a second party for the highest-impact actions. Any control the administrator can disable or edit provides no assurance against that administrator.'),
('CISSP (Certified Information Systems Security Professional)','Domain 8: Software Development Security','exam','A report is generated by concatenating a user-supplied filter into a SQL statement. Which remedy removes the vulnerability class rather than one instance?','Escape single quotes in the input','Use parameterised statements so user input is never parsed as SQL, with allowlisted identifiers where structure must vary','Rename the table','Restrict the page to authenticated users','B','Parameterisation separates code from data at the protocol level, so no input can alter the statement structure. Escaping is an incomplete denylist and authentication only changes who can attempt the injection.'),
('CISSP (Certified Information Systems Security Professional)','Domain 8: Software Development Security','exam','A client application hides the delete button for non-privileged users, and the server accepts any delete request. Which vulnerability class is this?','Cross-site scripting','Broken access control, because authorisation is enforced only in the interface and not at the server that performs the action','Insecure deserialisation','Security misconfiguration','B','Authorisation must be decided by the component that performs the action, since a client can issue any request regardless of what it renders. Hiding a control changes presentation, not permission.'),
('CISSP (Certified Information Systems Security Professional)','Domain 8: Software Development Security','hard','A dependency update introduces a transitive package with a known critical vulnerability. Which practice would have caught this before release, and what is the durable control?','Manual reading of the changelog','Only running the unit tests','Generating a software bill of materials and scanning dependencies including transitive ones in the pipeline, with a policy that blocks release above an agreed severity','Pinning the direct dependency version only','C','A bill of materials makes transitive components visible and pipeline scanning turns that visibility into a blocking gate. Pinning direct versions leaves the transitive tree free to move and changelog reading does not scale.'),
('CISSP (Certified Information Systems Security Professional)','Domain 8: Software Development Security','exam','Threat modelling is introduced. When does it deliver most value?','After the penetration test','During design, so trust boundaries, data flows and abuse cases shape the architecture before it is expensive to change','At the end of the release','Only for systems handling payments','B','Modelling threats while the design is still malleable lets the boundaries and mitigations be built in rather than retrofitted. Done after implementation it reports defects instead of preventing them.'),
('CISSP (Certified Information Systems Security Professional)','Domain 8: Software Development Security','exam','An application deserialises objects from an untrusted client to restore session state. What is the safest correction?','Sign the serialised blob and continue deserialising arbitrary types','Compress the payload','Increase the payload size limit','Do not deserialise untrusted data into arbitrary types: accept a simple data format, validate it against a strict schema, and reconstruct the object server-side','D','Restricting the input to a plain data format validated against a schema removes the ability of the payload to select types or trigger construction side effects. A signature protects integrity but still permits any type the trusted signer can be induced to emit.')
) as v(certification, syllabus_area, difficulty, question, option_a, option_b, option_c, option_d, correct_option, rationale)
where not exists (select 1 from public.certification_exam_question where certification = 'CISSP (Certified Information Systems Security Professional)');

-- ================ CEH (Certified Ethical Hacker) ================
insert into public.certification_exam_question
  (certification, syllabus_area, difficulty, question, option_a, option_b, option_c, option_d, correct_option, rationale)
select * from (values
('CEH (Certified Ethical Hacker)','Footprinting and Reconnaissance','exam','An engagement begins and the tester must map the target attack surface without sending a single packet to the target infrastructure. Which activity is appropriate?','Passive reconnaissance: certificate transparency logs, public DNS records, job adverts, code repositories and archived pages','A full TCP connect scan of the published range','Credentialed vulnerability scanning','Password spraying against the login portal','A','Passive reconnaissance draws only on third-party and public sources, so the target sees no traffic from the tester. Every other option sends packets to the target and is therefore active.'),
('CEH (Certified Ethical Hacker)','Footprinting and Reconnaissance','exam','Certificate transparency logs are queried for a target domain. What is the practical value to the tester?','They reveal server passwords','They disclose subdomain names, including internal-sounding hosts, that were never published in public DNS','They list open ports','They prove the certificate is revoked','B','Every issued certificate is logged with its subject names, which frequently exposes staging, admin and internal hostnames. It is a naming disclosure, not a port or credential disclosure.'),
('CEH (Certified Ethical Hacker)','Footprinting and Reconnaissance','hard','Before any testing begins, which document defines what the tester may touch and protects both parties legally?','The vulnerability report template','The network diagram','A signed scope and rules of engagement with written authorisation, defining in-scope assets, permitted techniques, timing and escalation contacts','The invoice','C','Written authorisation with an explicit scope is what separates an authorised test from an offence, and it fixes the techniques and windows in advance. No technical artefact provides that protection.'),
('CEH (Certified Ethical Hacker)','Footprinting and Reconnaissance','exam','A tester discovers an employee posting an internal build server hostname in a public forum. Which risk does this most directly create?','It weakens the encryption in use','It exhausts the server memory','It invalidates the certificate','It gives an attacker a named internal target for later phishing and direct access attempts, shrinking the reconnaissance effort required','D','Leaked internal names reduce the attacker search space and make pretexting far more convincing. It is a disclosure problem rather than a cryptographic or resource problem.'),
('CEH (Certified Ethical Hacker)','Scanning Networks','exam','A tester needs to know which of 4,000 addresses are live while generating as little traffic as possible. Which approach fits?','A host discovery sweep first, then port scanning only the responsive hosts','A full 65,535-port scan of every address','An aggressive service version scan of every address','A UDP scan of every address','A','Discovering live hosts first reduces the subsequent scan to a small fraction of the range. Scanning every port of every address multiplies traffic and time for no additional early information.'),
('CEH (Certified Ethical Hacker)','Scanning Networks','exam','A SYN scan of a port returns a RST packet. What does the tester conclude?','The port is open','The port is closed, because the host actively refused the connection attempt','The port is filtered','The host is offline','B','A reset is an explicit refusal from a reachable host, which means closed rather than filtered. A filtered port typically produces no response at all or an ICMP administratively-prohibited message.'),
('CEH (Certified Ethical Hacker)','Scanning Networks','hard','Scans from one source address stop returning results after a few minutes, while a different source still works. What is the most likely cause and the correct professional response?','The target has crashed, so the test should stop','The scanner is misconfigured, so it should be reinstalled','Rate-based blocking by an intrusion prevention device has blacklisted the source, so the tester should slow the scan, note the detection in the report and coordinate with the client','The network is congested, so the scan should be run faster','C','Losing one source while another works is the signature of source-based blocking by a defensive device, and its detection is itself a finding worth reporting. Speeding up would deepen the block and disrupt the client.'),
('CEH (Certified Ethical Hacker)','Scanning Networks','exam','Which scan result state means the tester received no response and cannot distinguish a listening service from a dropped packet?','Open','Closed','Unfiltered','Filtered','D','A filtered result records that a packet-filtering device silently discarded the probe, leaving the service state unknown. Open and closed both require a response to be observed.'),
('CEH (Certified Ethical Hacker)','Enumeration','hard','An anonymous connection to an exposed service returns a list of user accounts and group memberships. Why is this significant and what is the remediation?','It is harmless because no passwords were revealed','It proves the service is patched','It hands an attacker a validated username list for password spraying and social engineering, so anonymous enumeration must be disabled and the service restricted to authenticated internal callers','It only affects availability','C','Valid usernames turn an unbounded guessing problem into a targeted one and make pretexting credible. The fix is to remove the anonymous binding and restrict the service, not to rely on password strength.'),
('CEH (Certified Ethical Hacker)','Enumeration','exam','An SNMP agent responds to the community string public. What has the tester obtained and why does it matter?','Nothing useful','Read access to device configuration detail such as interfaces, routes, running processes and neighbours, which maps the internal network','Administrative shell on the device','The device encryption keys','B','A default read community exposes a detailed inventory of the device and its neighbours, which accelerates internal mapping. It is a read disclosure rather than direct code execution.'),
('CEH (Certified Ethical Hacker)','Enumeration','hard','A login endpoint returns user not found for unknown accounts and wrong password for known ones. Which flaw is this and how is it fixed?','Broken cryptography, fixed by a stronger hash','Denial of service, fixed by rate limiting alone','A user enumeration flaw, fixed by returning an identical generic failure and an equal response time for both cases, alongside rate limiting','No flaw, since the messages help users','C','Differing messages or timings let an attacker confirm which accounts exist without ever guessing a password. Only an indistinguishable response in both content and timing closes the oracle.'),
('CEH (Certified Ethical Hacker)','Enumeration','exam','Banner grabbing on a service returns a precise product and version string. What is the immediate consequence for the target?','It improves performance','It authenticates the tester','It has no effect','The exact version can be matched against public vulnerability databases, so the target has disclosed which known exploits are worth attempting','D','A precise version turns broad reconnaissance into a short exploit shortlist. Suppressing or genericising banners does not fix the vulnerability but removes the free targeting information.'),
('CEH (Certified Ethical Hacker)','Vulnerability Analysis','exam','A scanner reports a critical finding on a host, but the affected module is not loaded and the port is unreachable from any network. How should the tester classify it?','As a false positive in practice, downgraded with the reason recorded, because the vulnerable code path is not reachable','As critical regardless','As a configuration error','As a denial of service finding','A','Risk depends on reachability and exploitability, not on the presence of a version string alone. The professional response is to verify and record why the finding was downgraded rather than to pass the raw scanner output along.'),
('CEH (Certified Ethical Hacker)','Vulnerability Analysis','exam','Two findings share a CVSS base score of 8.1. One is on an internet-facing checkout service and the other on an isolated laboratory host. How should remediation be ordered?','Strictly by base score, so they are equal','By environmental and temporal context, so the internet-facing revenue path is remediated first','Alphabetically by host','By whichever is easier to patch','B','The base score describes intrinsic severity and must be adjusted by exposure and business impact to produce a priority. Treating base scores as final priority ignores exactly the context the scoring system expects to be applied.'),
('CEH (Certified Ethical Hacker)','Vulnerability Analysis','hard','A credentialed scan finds far more issues than the unauthenticated scan of the same host. What does the difference tell the tester?','The credentialed scan is faulty','The host has been compromised','The unauthenticated view shows what a remote attacker sees first, while the credentialed view shows the full patch state, so both are needed and the gap describes post-access exposure','Nothing, they should be identical','C','An unauthenticated scan measures remote attack surface while a credentialed scan measures internal patch state, and the difference is the exposure that follows a foothold. Neither view alone describes the risk.'),
('CEH (Certified Ethical Hacker)','Vulnerability Analysis','exam','During a test the tester finds an unrelated, actively exploited compromise on a client host. What is the correct action?','Continue the test and mention it in the final report','Attempt to remove the malware personally','Ignore it as out of scope','Stop, invoke the escalation path in the rules of engagement and notify the client contact immediately','D','Evidence of an active compromise is an incident, and the rules of engagement define the immediate escalation for exactly this case. Waiting for the report or acting as an incident responder both exceed the mandate and cost the client time.'),
('CEH (Certified Ethical Hacker)','System Hacking','exam','After capturing password hashes, the tester logs in to another host by presenting the hash itself without ever recovering the plaintext. Which technique is this and which control breaks it?','Pass the hash, mitigated by unique local credentials per host, restricting privileged logon types and network segmentation','A rainbow table attack, mitigated by salting','A dictionary attack, mitigated by longer passwords','A brute force attack, mitigated by lockout','A','Pass the hash reuses the stored credential material directly, so password strength is irrelevant to it. Unique per-host credentials and restricted privileged logons remove the reuse the technique depends on.'),
('CEH (Certified Ethical Hacker)','System Hacking','exam','A low-privilege foothold is escalated by exploiting a service that runs as root and is writable by the tester account. Which class of weakness is this?','A cryptographic weakness','A local privilege escalation via insecure file or service permissions, where a lower-privileged principal can alter what a higher-privileged process executes','A network denial of service','A session fixation flaw','B','When a privileged process executes content that a lower-privileged user can modify, the privilege boundary is already broken. The fix is ownership and permissions on the executed content, not on the exploit.'),
('CEH (Certified Ethical Hacker)','System Hacking','hard','Password spraying is chosen over brute forcing a single account. What is the attacker reasoning and the defensive countermeasure?','Spraying is faster per account, countered by longer passwords','Spraying works only on old systems, countered by patching','Spraying tries a few common passwords across many accounts to stay under per-account lockout thresholds, countered by multi-factor authentication plus detection of many failures across distinct accounts from one source','Spraying decrypts the hash store, countered by encryption','C','Lockout counters are per account, so spreading a small number of guesses across many accounts avoids them entirely. Detection must therefore be horizontal, and a possession factor removes the value of a guessed password.'),
('CEH (Certified Ethical Hacker)','System Hacking','exam','A tester obtains a valid session token from a log file and reuses it to act as that user. Which control would have prevented the reuse?','Longer session tokens','A longer session timeout','More verbose logging','Binding the session to client attributes, short expiry with rotation on privilege change, and never writing tokens into logs','D','A bearer token is authority in itself, so the controls are to stop it being recorded, to shorten its life and to bind it so a stolen copy fails elsewhere. Length does not help against a token that was disclosed rather than guessed.'),
('CEH (Certified Ethical Hacker)','Maintaining Access and Covering Tracks','exam','An attacker adds a scheduled task that reconnects to a controlled host every hour. Which phase is this and which detection is most effective?','Persistence, detected by alerting on new or modified scheduled tasks and services and on unexpected outbound connections to unknown destinations','Reconnaissance, detected by firewall logs','Scanning, detected by an intrusion detection signature','Enumeration, detected by account auditing','A','Establishing a mechanism that survives reboot and logout is persistence, and it is detected by watching the mechanisms themselves plus the egress they need. Reconnaissance and scanning happen before access is obtained.'),
('CEH (Certified Ethical Hacker)','Maintaining Access and Covering Tracks','exam','Log entries covering the intrusion window are missing from a compromised host. Which control would have preserved the record?','Increasing the local log file size','Forwarding logs in real time to an append-only central store that the host account cannot modify or delete','Rotating the logs more often','Compressing the logs','B','Once the host is controlled, any log the host can edit is untrustworthy, so evidence must leave the host immediately and land where the host cannot reach it. Local sizing and rotation change nothing about who can delete the file.'),
('CEH (Certified Ethical Hacker)','Maintaining Access and Covering Tracks','hard','Timestamps on several system binaries have been altered to match the surrounding files. Which technique is this and how is it detected?','Steganography, detected by entropy analysis','Log injection, detected by parsing errors','Timestomping, detected by comparing file system metadata timestamps against an off-host integrity baseline and against records that the attacker could not reach','Packing, detected by signature scanning','C','Editing timestamps to blend in is timestomping, and it is defeated by comparison with evidence held outside the compromised host. Anything measured only on the host can be edited by whoever controls it.'),
('CEH (Certified Ethical Hacker)','Maintaining Access and Covering Tracks','exam','At the end of an authorised engagement, what must the tester do with the accounts, tools and footholds created during the test?','Leave them for the next engagement','Hand the credentials to the client help desk','Delete them silently','Remove every artefact, document each one that was created and removed in the report, and confirm removal with the client','D','An unremoved foothold is a real vulnerability the tester introduced, and the client needs the list to verify the environment is clean. Silent deletion leaves the client unable to confirm what existed.'),
('CEH (Certified Ethical Hacker)','Hacking Web Applications','exam','A page reflects a URL parameter into the HTML without encoding, and the tester executes script in a victim browser. Which flaw is this and what is the primary fix?','Reflected cross-site scripting, fixed by contextual output encoding at the point of rendering, supported by a restrictive content security policy','Cross-site request forgery, fixed by a token','SQL injection, fixed by parameterisation','Directory traversal, fixed by path normalisation','A','The defect is that untrusted data is emitted into a markup context without encoding for that context, so encoding at output is the fix. A content security policy is defence in depth and does not remove the underlying defect.'),
('CEH (Certified Ethical Hacker)','Hacking Web Applications','exam','Changing an invoice identifier in a URL returns another customer invoice. Which flaw is this and what is the fix?','Cross-site scripting, fixed by encoding','An insecure direct object reference and broken object level authorisation, fixed by checking on the server that the authenticated principal owns the requested object','Session fixation, fixed by rotating the session','Clickjacking, fixed by frame options','B','The server is retrieving an object by identifier without asking whether the caller may see it, so ownership must be checked on every request. Unguessable identifiers only make the flaw harder to find, not absent.'),
('CEH (Certified Ethical Hacker)','Hacking Web Applications','hard','A server-side feature fetches a URL supplied by the user, and the tester makes it retrieve an internal metadata endpoint. Which attack is this and which mitigation is decisive?','Cross-site request forgery, mitigated by same-site cookies','Open redirect, mitigated by a warning page','Server-side request forgery, mitigated by an allowlist of permitted destinations, blocking link-local and internal ranges after resolution, and removing the credentials the internal endpoint would return','Cross-site scripting, mitigated by encoding','C','The server is being used as a proxy into a network the attacker cannot reach, so the destination must be constrained after name resolution to defeat rebinding. Removing the reachable credential endpoint eliminates the prize even if a request escapes.'),
('CEH (Certified Ethical Hacker)','Hacking Web Applications','exam','A state-changing request succeeds when a victim visits an attacker page while logged in, and no unpredictable value is required. Which flaw is this?','Cross-site scripting','Broken cryptography','Insecure deserialisation','Cross-site request forgery, addressed by an unpredictable per-request token and SameSite cookie handling','D','The browser attaches the session automatically, so the server must require something the attacker cannot know or send from another origin. A per-request token plus SameSite handling supplies exactly that.'),
('CEH (Certified Ethical Hacker)','SQL Injection','exam','A search field is tested with a single quote and the response returns a database syntax error. What has the tester established?','That input reaches the SQL parser unescaped, indicating injection, and that the application is also leaking internal errors to the client','That the database is offline','That the field is safely parameterised','That the field is numeric','A','A parser error proves the input is being concatenated into the statement rather than bound as a parameter. Returning that error to the client is a second defect, since it discloses internal structure.'),
('CEH (Certified Ethical Hacker)','SQL Injection','hard','A page returns no data and no error, but a payload causing a deliberate delay makes the response measurably slower. Which technique is in use and what does it prove?','Union-based injection, proving column count','Time-based blind SQL injection, proving the input is executed by the database even though no output or error is returned','Error-based injection, proving the schema','Second-order injection, proving stored payloads','B','When neither data nor errors are reflected, a measurable timing difference is the channel that proves execution. It confirms exploitability that an output-based test would have missed entirely.'),
('CEH (Certified Ethical Hacker)','SQL Injection','exam','A team responds to an injection finding by adding a web application firewall rule that blocks the observed payload. Why is this insufficient?','Firewalls slow the application','It blocks one encoding of one payload while the vulnerable concatenation remains, so equivalent payloads still reach the parser; parameterised statements remove the class','Firewalls cannot inspect HTTPS','It breaks the database index','B','Filtering treats symptoms and is defeated by encoding, casing and alternative syntax, because the underlying statement is still built by concatenation. Only separating code from data at the query level removes the class.'),
('CEH (Certified Ethical Hacker)','SQL Injection','exam','Beyond parameterisation, which measure most limits the damage of a successful injection against an application database account?','Longer database passwords','More frequent backups','A larger connection pool','Least privilege for the application role, with no ownership or DDL rights and row-level security enforcing tenant isolation','D','A constrained role bounds what a successful injection can read or destroy, which is what defence in depth means here. Password length and backups do not restrict what the compromised session may do.'),
('CEH (Certified Ethical Hacker)','Cryptography','exam','A system stores user passwords using a fast general-purpose hash with no salt. What are the two distinct weaknesses?','Nothing is wrong','Precomputed tables work because there is no salt, and the speed of the function makes offline guessing cheap, so a salted memory-hard function with a tuned work factor is required','Only the missing salt matters','Only the speed matters','B','The missing salt permits precomputation shared across all users, and the speed permits very high guess rates per user. Both must be addressed, which is why modern password hashes are salted and deliberately expensive.'),
('CEH (Certified Ethical Hacker)','Cryptography','hard','A protocol encrypts a message and appends an unauthenticated checksum. Which risk remains and what is the correct construction?','None, encryption implies integrity','Only confidentiality is at risk','Ciphertext can be altered undetectably because the checksum is not keyed, so an authenticated encryption mode or encrypt-then-MAC with a separate key must be used','Only replay is at risk','C','Encryption without authentication leaves the ciphertext malleable and a non-keyed checksum can be recomputed by the attacker. Authenticated encryption binds integrity to a key so tampering is detected.'),
('CEH (Certified Ethical Hacker)','Cryptography','exam','A tester finds that the same initialisation vector is reused across messages with the same key in a stream mode. What is the consequence?','Performance degrades','Keystream is reused, so combining two ciphertexts cancels the keystream and reveals relationships between the plaintexts','The key is rotated automatically','The message is padded incorrectly','B','Reusing a nonce with the same key reproduces the keystream, and combining the ciphertexts removes it entirely. That is why nonce uniqueness is a hard requirement rather than a recommendation.'),
('CEH (Certified Ethical Hacker)','Cryptography','exam','A client accepts any certificate presented by the server because validation was disabled to fix a deployment error. What is the resulting exposure?','Only a performance cost','Only a logging gap','No exposure while the network is private','An active interceptor can present its own certificate and read and modify the whole session, so transport encryption provides no assurance at all','D','Without validation the encrypted channel may terminate at an attacker, which defeats both confidentiality and integrity. The correct fix is to trust the proper chain, not to disable the check.'),
('CEH (Certified Ethical Hacker)','Cloud Computing','exam','An object storage bucket holding customer documents is found readable by anonymous users. Which correction is complete?','Rename the bucket','Remove public access at both the bucket policy and the account-level public access block, rotate anything sensitive that was exposed, and review access logs for prior reads','Move the bucket to another region','Add a robots.txt file','B','Closing the exposure means removing every grant that permitted it and enforcing the account-level block, then treating what was exposed as disclosed. Obscurity measures leave the data reachable by anyone who knows the name.'),
('CEH (Certified Ethical Hacker)','Cloud Computing','exam','A compromised workload retrieves credentials from the instance metadata service and uses them elsewhere. Which mitigations apply?','Rotate the account password','Disable logging to reduce noise','Require session-oriented metadata access with a hop limit, scope the attached role to least privilege, and prefer short-lived workload identity over attached long-lived permissions','Increase the instance size','C','Hardening the metadata path blocks the common server-side request forgery route, while a tightly scoped short-lived identity limits what a stolen credential can do. Neither password rotation nor sizing touches that path.'),
('CEH (Certified Ethical Hacker)','Cloud Computing','exam','Under the shared responsibility model for a managed database service, which item remains the responsibility of the customer?','Physical security of the data centre','Patching the underlying hypervisor','Replacing failed disks','Access control, network exposure, encryption key policy and the data itself','D','The provider secures the infrastructure and the managed platform, while configuration, identity and data remain with the customer. Misreading that boundary is the origin of most cloud data exposures.'),
('CEH (Certified Ethical Hacker)','Cloud Computing','exam','A serverless function is granted a broad role because scoping it precisely was inconvenient. Which finding should the tester report and with what recommendation?','No finding, roles are internal','Excessive permissions, recommending a role scoped to the specific actions and resources the function uses, derived from its observed access, with the broad grant removed','A denial of service risk only','A cryptographic finding','B','An over-broad role converts any compromise of the function into access far beyond its purpose, which is a real and reportable finding. The recommendation is a role derived from actual usage rather than from convenience.')
) as v(certification, syllabus_area, difficulty, question, option_a, option_b, option_c, option_d, correct_option, rationale)
where not exists (select 1 from public.certification_exam_question where certification = 'CEH (Certified Ethical Hacker)');

-- ============ ISTQB Advanced Level Test Manager ============
insert into public.certification_exam_question
  (certification, syllabus_area, difficulty, question, option_a, option_b, option_c, option_d, correct_option, rationale)
select * from (values
('ISTQB Advanced Level Test Manager','Managing the Test Activities','exam','A test manager must produce a test plan for a release whose scope is still moving. Which planning approach fits and why?','Iterative planning, with the plan revisited each iteration as scope and risk change, and the master plan holding only what is stable','A single detailed plan fixed at the start and frozen','No plan until the scope is final','A plan produced after test execution ends','A','Planning is a continuous activity, so the plan is revised as new information about scope and risk arrives. A frozen plan against moving scope becomes inaccurate immediately and stops being used.'),
('ISTQB Advanced Level Test Manager','Managing the Test Activities','exam','Which pair correctly describes entry and exit criteria for a test level?','Entry criteria describe defects found and exit criteria describe test cases written','Entry criteria state what must be true before test execution may usefully start, and exit criteria state the conditions, including residual risk, under which the level is declared complete','Both describe the schedule only','Exit criteria are the same as the definition of ready','B','Entry criteria protect the level from starting on an untestable object, and exit criteria make completion a decision against stated conditions rather than a date. Mixing them up leaves the level starting and finishing on schedule pressure alone.'),
('ISTQB Advanced Level Test Manager','Managing the Test Activities','hard','A weekly report states that 82% of planned test cases have been executed. The sponsor asks whether the release is safe. Why is that metric insufficient?','It is sufficient','It is only wrong if the total is unknown','Execution progress measures activity, not risk coverage; the sponsor needs coverage of the high-risk areas, the outstanding defects by severity and the residual risk, since the unexecuted 18% may hold all the critical risk','It is only insufficient for agile projects','C','A count of executed cases says nothing about which risks those cases addressed, so the same percentage can mean very different exposure. The release decision needs risk coverage and residual risk, not throughput.'),
('ISTQB Advanced Level Test Manager','Managing the Test Activities','exam','Test monitoring shows the team consistently behind plan. Which action is test control rather than test monitoring?','Producing the burndown chart','Recording the number of tests run','Presenting the metrics at the weekly meeting','Reprioritising the remaining tests towards the highest risks and reallocating effort in response to the measurement','D','Monitoring gathers the information and control is the corrective action taken in response to it. Reporting the same numbers again without acting changes nothing about the outcome.'),
('ISTQB Advanced Level Test Manager','Managing the Test Activities','exam','An estimate produced by the test manager is halved by the project manager without any change in scope. What is the professional response?','Accept the reduction quietly','Restate the estimate with its basis and assumptions, present the scope or risk coverage that must be removed to fit the reduced effort, and record the accepted residual risk in writing','Refuse to test','Reduce the estimate further to avoid conflict','B','An estimate is a claim about effort for a scope, so a smaller number requires a smaller scope and the trade must be made explicit. Recording the residual risk keeps the decision with the party who made it.'),
('ISTQB Advanced Level Test Manager','Managing the Test Activities','hard','Which estimation technique gives the most defensible number when historical data from comparable releases exists?','Expert judgement alone','Metrics-based estimation from historical effort and defect data for comparable work, cross-checked against expert judgement','Doubling the developer estimate','Using the time remaining until the deadline','B','Historical data grounds the estimate in what the organisation actually achieved, and expert review catches where this release differs. Deriving effort from the deadline is scheduling, not estimation.'),
('ISTQB Advanced Level Test Manager','Managing the Test Activities','exam','A test manager must define the test approach for a safety-relevant component and a low-impact reporting screen in the same release. What is correct?','One uniform approach for both, for consistency','Test only the safety-relevant component','No formal approach is needed','A differentiated approach, with rigour, techniques and independence scaled to the risk level of each item','D','The approach is chosen to match risk, so uniform rigour either wastes effort on the trivial item or under-tests the critical one. Differentiation is what makes the overall effort proportionate.'),
('ISTQB Advanced Level Test Manager','Managing the Test Activities','exam','Which statement about the independence of testing is correct?','Greater independence is always better regardless of cost','Independence reduces author bias and finds different defects, but it can also reduce domain knowledge and delay feedback, so the level of independence is a deliberate trade-off per context','Independence has no effect on defect detection','Only fully outsourced testing counts as independent','B','Independence brings a different perspective at the cost of proximity to the work, and both effects are real. The manager chooses the level that fits the risk and the feedback speed the project needs.'),
('ISTQB Advanced Level Test Manager','Risk-Based Testing','hard','In risk-based testing, how is the risk level of a quality risk item determined and what does it drive?','By defect count alone, driving the report','By the likelihood of the defect occurring combined with the impact if it does, driving the depth, technique and sequence of testing for that item','By the developer preference, driving assignment','By the number of test cases already written, driving coverage','B','Risk level is the product of likelihood and impact, and it determines how much testing effort an item receives and how early it is tested. Divorcing risk from effort allocation makes the analysis decorative.'),
('ISTQB Advanced Level Test Manager','Risk-Based Testing','exam','Who should participate in the quality risk analysis workshop for a new payment feature?','The test manager alone','A cross-section of stakeholders including business, development, operations and testing, because likelihood and impact draw on different knowledge','Only the developers','Only the sponsor','B','Impact is a business judgement while likelihood is largely technical, so a single perspective systematically mis-scores one of the two. Broad participation also builds the shared commitment the mitigation plan needs.'),
('ISTQB Advanced Level Test Manager','Risk-Based Testing','hard','Testing is cut short by two weeks. How should a risk-based test manager decide what still gets tested?','Test whatever is easiest to finish','Test in the original order and stop when time runs out','Execute in descending risk order so the highest risks are covered first, then report the specific risks left untested as residual risk for the release decision','Test only new features and skip regression entirely','C','Executing highest risk first means an interruption at any point leaves the least important work undone. Naming the untested risks converts a schedule cut into an informed release decision rather than a silent gamble.'),
('ISTQB Advanced Level Test Manager','Risk-Based Testing','exam','Which is a product risk rather than a project risk?','The test environment is delivered late','A key tester resigns','The vendor contract is unsigned','The pricing calculation may produce an incorrect total under a currency rounding condition','D','A product risk is a possible failure in the deliverable itself, whereas late environments, staffing and contracts threaten the project that builds it. Mixing them leads to mitigation plans aimed at the wrong thing.'),
('ISTQB Advanced Level Test Manager','Risk-Based Testing','exam','Halfway through execution, several high-risk items have been thoroughly tested and found stable, while a newly discovered integration has had no testing. What should the manager do?','Continue with the original plan','Reassess the risks, lower the level of the items now shown to be stable, raise the new integration, and reallocate the remaining effort accordingly','Add test cases evenly across everything','Freeze the risk register until the next release','B','Risk analysis is revisited as evidence accumulates, because testing itself changes what is known about likelihood. A register frozen at the start stops directing effort where the remaining risk actually is.'),
('ISTQB Advanced Level Test Manager','Risk-Based Testing','hard','A stakeholder asks the test manager to state that the release contains no defects. What is the correct response?','Provide the statement if all planned tests passed','Explain that testing shows the presence of defects and cannot prove their absence, and report instead the risks covered, the defects found and open, and the residual risk for the areas tested and untested','Provide the statement with a disclaimer','Refuse to report anything','B','Exhaustive testing is not possible, so no amount of passing tests establishes absence of defects. The honest and more useful deliverable is a statement of coverage against risk and the residual risk that remains.'),
('ISTQB Advanced Level Test Manager','Defect Management','exam','Which set of fields makes a defect report actionable without a follow-up conversation?','The reporter name and the date only','A severity rating only','A screenshot only','Steps to reproduce, expected and actual result, environment and build identifier, severity and priority with their basis, and supporting evidence such as logs','D','A report is actionable when a developer can reproduce and locate the failure from the report alone. Severity or evidence in isolation leaves the reproduction step to be rediscovered.'),
('ISTQB Advanced Level Test Manager','Defect Management','exam','A defect crashes a rarely used administrative export, and another slightly misaligns a label on the checkout page seen by every customer. How should severity and priority be set?','The crash is high severity, and its priority may still be lower than the cosmetic defect if the business values the customer-facing appearance sooner','Severity and priority are always equal','Both are high priority by default','Priority is set by the developer workload','A','Severity describes the technical impact of the failure and priority describes the business urgency of the fix, and they legitimately diverge. Collapsing them into one field removes the business ability to sequence the work.'),
('ISTQB Advanced Level Test Manager','Defect Management','hard','A large share of defects are being returned as not reproducible. Which management response addresses the cause?','Instruct testers to raise fewer defects','Reopen every returned defect automatically','Analyse the returned reports for what was missing, tighten the report template and environment and build identification, and add a triage step where reporter and developer reproduce together before rejection','Accept the rejections and adjust the metrics','C','Not reproducible usually signals missing environment, build or state information rather than an absent defect, so the report and the triage step are what must change. Suppressing reports or auto-reopening treats the count instead of the information gap.'),
('ISTQB Advanced Level Test Manager','Defect Management','exam','What is the purpose of a defect triage meeting and who should attend?','To assign blame for the defects','To count defects for the weekly report','To decide priority, ownership and target release for each new defect, attended by testing, development and a business representative who can decide urgency','To rewrite the test cases','C','Triage exists to make a fix decision, which needs the technical assessment and the business urgency in the same room. Without a business decision maker the meeting can only guess at priority.'),
('ISTQB Advanced Level Test Manager','Defect Management','exam','Defect density is compared between two components and one shows far more defects. What must be established before drawing a conclusion?','That the component with fewer defects is better written','That both components received comparable test effort and coverage, since a low count can equally mean the component was barely tested','That the defect tool is the same','That the same tester worked on both','B','A defect count is a product of both the defects present and the effort spent looking, so an unmeasured denominator makes the comparison meaningless. Low counts from untested areas are the classic misreading.'),
('ISTQB Advanced Level Test Manager','Defect Management','hard','Which analysis of the defect database gives the most value for preventing future defects rather than fixing current ones?','Sorting defects by reporter','Counting defects per week','A defect causal analysis grouping defects by root cause and by the phase in which they were introduced and detected, so process changes can target where they originate','Listing defects alphabetically by component','C','Grouping by root cause and by introduction and detection phase shows where defects are created and how late they are caught, which is what a process change must target. Raw counts describe the symptom without locating its origin.'),
('ISTQB Advanced Level Test Manager','Defect Management','exam','A defect is closed as works as designed, but the tester believes the design itself is wrong. What is the correct handling?','Close the defect and move on','Reclassify it as a change or design issue and escalate it to the requirement owner for a decision, keeping the record linked so the risk is visible in the release decision','Reopen the defect repeatedly','Delete the defect record','B','The observation may be valid even when the implementation matches the specification, so it belongs with the party who owns the specification. Deleting or looping the record loses information the release decision needs.'),
('ISTQB Advanced Level Test Manager','Managing the Test Team','exam','A test team must be assembled for a release combining a regulated payment flow and an exploratory-heavy new interface. Which composition is most appropriate?','Only automation engineers','A mix of skills: domain and compliance knowledge for the payment flow, strong exploratory testers for the new interface, and automation capability for regression','Only manual testers','Only junior testers to reduce cost','B','Team composition follows the work, and the two parts of this release demand genuinely different competencies. A single-skill team leaves one of the two areas materially under-tested.'),
('ISTQB Advanced Level Test Manager','Managing the Test Team','exam','A tester is repeatedly in conflict with a developer over defect severity. What should the test manager do?','Instruct the tester to lower every severity','Move the tester to another project','Make the severity criteria explicit and shared, have both parties apply them to the disputed defects, and escalate only the remaining genuine disagreements to triage','Escalate every disagreement to the sponsor','C','Most severity disputes come from an unstated definition, so writing the criteria down converts opinion into an applicable rule. Personnel moves and blanket instructions leave the ambiguity in place for the next pair of people.'),
('ISTQB Advanced Level Test Manager','Managing the Test Team','hard','How should a test manager evaluate the performance of an individual tester?','By the number of defects raised','By the number of test cases executed','By the pass rate of the tests they ran','By a balanced view including the value and clarity of the defects found, coverage of the risks owned, quality of analysis and collaboration, since raw counts are easily gamed and reward volume over value','D','Counting defects or executions rewards quantity and can be inflated at the cost of usefulness. A balanced assessment measures the contribution to informed release decisions, which is the actual purpose of the role.'),
('ISTQB Advanced Level Test Manager','Managing the Test Team','exam','A distributed test team spans three time zones and defects are stalling for a day at each handover. Which management action addresses this directly?','Require everyone to work the same hours','Define a handover protocol with a written status per item and an overlap window, and give each site end-to-end ownership of specific risk areas rather than splitting each item','Stop distributed working','Add a daily status email','B','Ownership of whole areas removes most of the handovers, and a defined protocol with an overlap window makes the remaining ones cost minutes rather than a day. Extra reporting documents the delay without removing it.'),
('ISTQB Advanced Level Test Manager','Test Tools and Automation','exam','A regression suite takes eleven hours and blocks the release pipeline. Which analysis should precede any tooling change?','Buy a faster server immediately','Delete the slowest tests','Analyse the suite for value and duplication, keep the tests that cover real risk, remove duplicates and obsolete cases, then parallelise and stage the remainder so the risky subset runs first','Run the suite weekly instead','C','Speeding up a suite full of duplicate and low-value tests optimises waste, so the content is examined before the infrastructure. Staging the risky subset first also returns useful information long before the full run completes.'),
('ISTQB Advanced Level Test Manager','Test Tools and Automation','exam','A business case for test automation is being written. Which measure best expresses the expected benefit?','The number of test cases automated','The reduction in repeated manual regression effort and the shortened feedback time to developers, set against the build and maintenance cost over the expected life of the tests','The licence cost of the tool','The number of scripts per tester','B','The benefit of automation is repeated execution and faster feedback, and it must be weighed against the ongoing maintenance the scripts will require. Counting automated cases measures activity rather than value.'),
('ISTQB Advanced Level Test Manager','Test Tools and Automation','hard','Automated tests fail intermittently and the team reruns them until they pass. What is the risk and the correct management action?','No risk, reruns are efficient','Reruns improve stability over time','The tests are simply slow','Retrying until green also converts genuine intermittent regressions into passes, so the flaky tests must be quarantined out of the release gate and fixed, with the quarantine visible and time-boxed','D','A rerun-until-green policy destroys the ability of the suite to detect a whole class of real defect, because it cannot tell flakiness from a real intermittent failure. Quarantine keeps the gate honest while the underlying instability is fixed.'),
('ISTQB Advanced Level Test Manager','Test Tools and Automation','exam','A tool is proposed that no one in the team has used. What should a pilot establish before organisation-wide adoption?','That the vendor is reputable','That the licence is affordable','That the tool fits the actual technology and process, what the learning curve and maintenance cost really are, and that it integrates with the existing pipeline and defect management','That competitors use it','C','A pilot exists to replace vendor claims with measurements from the real context, including the integration and maintenance costs that dominate the total. Price and reputation are decided before the pilot, not by it.'),
('ISTQB Advanced Level Test Manager','Improving the Testing Process','hard','A test process improvement initiative is being launched. Which sequence follows accepted improvement practice?','Buy a tool and then measure the result','Assess the current process against a defined model or against measured problems, agree improvement objectives with stakeholders, implement changes in priority order, then measure against the objectives and repeat','Rewrite all test cases first','Increase the number of testers and reassess later','B','Improvement is a measured cycle that starts from an assessment and ends by checking the objectives it set, otherwise there is no way to know whether anything improved. Buying tools or adding people are possible actions, not the method.'),
('ISTQB Advanced Level Test Manager','Improving the Testing Process','exam','Which distinguishes a process-model-based improvement approach from an analytical one?','They are identical','A process-model approach compares the organisation against a reference model of good practice, while an analytical approach derives improvements from the organisation own measured data such as causal analysis of its defects','Only the analytical approach uses metrics','Only the model-based approach can be repeated','B','A reference model supplies an external benchmark of practice, whereas analytical improvement starts from the specific evidence the organisation has generated. The two answer different questions and are often combined.'),
('ISTQB Advanced Level Test Manager','Improving the Testing Process','hard','A retrospective produces twenty improvement actions and none are implemented before the next retrospective. What should the test manager change?','Hold retrospectives less often','Stop holding retrospectives','Select a small number of the highest-value actions, give each a named owner and a date, track them to completion in the same place as other work, and review the closed actions at the next retrospective','Record more actions to increase the chance some are done','C','Improvement comes from completed actions, so a short owned and tracked list beats a long unowned one. Reviewing closure at the next session is what stops the list resetting each time.'),
('ISTQB Advanced Level Test Manager','Improving the Testing Process','exam','Which metric would best show whether an improvement aimed at finding defects earlier has worked?','The total number of defects found','The number of test cases written','Defect detection percentage by phase, or the shift in the distribution of defects towards earlier phases and away from post-release','The size of the test team','C','The objective was earlier detection, so the measure must be the phase distribution rather than the total. A raw total can move for many reasons unrelated to when defects are caught.'),
('ISTQB Advanced Level Test Manager','Improving the Testing Process','exam','Reviews are introduced to catch requirement defects earlier, but the team reports that reviews take too long and find little. What is the most likely cause and the correction?','Reviews never work','Reviews should be replaced with more testing','The reviewers are unqualified and should be replaced','The reviews lack defined entry criteria, roles, checklists and a focus on the highest-risk requirements, so they should be scoped and prepared rather than abandoned','D','Unfocused reviews of unprepared material consume time without finding much, which is a process defect rather than evidence against reviews. Defined roles, checklists and risk-based selection are what make review effort pay.'),
('ISTQB Advanced Level Test Manager','Managing the Test Activities','exam','A release decision must be made and one high-risk area remains untested because its environment was never delivered. What must the test manager report?','That testing is complete','That the untested area is low risk','That the area is untested, why, the specific risks that therefore remain uncovered, and what would be needed to cover them, leaving the acceptance decision with the accountable stakeholder','That the release should be cancelled','C','The test manager supplies the evidence and the residual risk, and the accountable stakeholder makes the go decision. Reporting completion or downgrading the risk to avoid conflict removes the information the decision depends on.'),
('ISTQB Advanced Level Test Manager','Managing the Test Activities','exam','Which item belongs in a test completion report rather than in a test plan?','The test approach and the entry criteria','The estimated effort and the schedule','The staffing plan','The measured coverage achieved, defects found and outstanding by severity, deviations from the plan and the residual risk at completion','D','A plan states intent before the work and a completion report states what was actually achieved and what risk remains. Confusing them produces reports that restate the plan instead of the outcome.'),
('ISTQB Advanced Level Test Manager','Risk-Based Testing','exam','A risk register entry has a mitigation of test thoroughly. Why is that inadequate?','It is adequate','It is only inadequate for low risks','It names no specific test technique, coverage level, responsible party or completion criterion, so nobody can tell whether the mitigation was performed or whether the risk was reduced','It should specify a tool','C','A mitigation must be specific enough to be executed and verified, otherwise the register records an intention rather than a control. Without a completion criterion the risk cannot be closed on evidence.'),
('ISTQB Advanced Level Test Manager','Defect Management','exam','What does a defect that escaped to production tell the test manager about the process?','That the tester was careless','That an escape analysis should ask which risk was not identified, which test would have caught it and why it was absent or passed, and feed that answer into the risk analysis and test design for future releases','That test cases should be doubled','That the defect should be closed quietly','B','An escaped defect is direct evidence about a gap in risk analysis, test design or execution, and its value lies in locating that gap. Attributing it to an individual or adding volume misses the specific mechanism that let it through.'),
('ISTQB Advanced Level Test Manager','Managing the Test Team','exam','A new tester joins a team testing a complex domain. What is the fastest route to useful contribution while managing risk?','Assign the highest-risk area immediately','Pair the new tester with an experienced one on medium-risk areas, with review of their analysis, and widen the scope as demonstrated competence grows','Restrict them to documentation for six months','Assign them only to automated test maintenance','B','Paired work on medium-risk items gives real learning while a second pair of eyes limits the exposure. Both extremes either risk the critical area or waste the capacity entirely.'),
('ISTQB Advanced Level Test Manager','Test Tools and Automation','exam','Which is the strongest indicator that an automated regression suite has become a liability rather than an asset?','The suite grows each release','The suite runs in a pipeline','Maintenance of the scripts consumes more effort than the manual execution it replaced, and failures are routinely assumed to be the fault of the tests rather than the product','The suite uses an open source tool','C','When maintenance exceeds the effort saved and failures are no longer believed, the suite has stopped supplying the trust it exists to provide. Growth and tooling choices say nothing about that balance.')
) as v(certification, syllabus_area, difficulty, question, option_a, option_b, option_c, option_d, correct_option, rationale)
where not exists (select 1 from public.certification_exam_question where certification = 'ISTQB Advanced Level Test Manager');

-- ============ key-letter balancing (deterministic, idempotent) ============
-- The banks above are authored with the key deliberately moved around the four positions, but
-- hand authoring drifts. This block levels each bank to exactly ten keys per letter by swapping
-- the text of two options on the lowest-id row of the most common letter into the least common
-- letter. It reads the live distribution, so once a bank is level it does nothing at all.
do $rebalance$
declare
  cert text;
  over_letter char(1);
  under_letter char(1);
  spread int;
  rid bigint;
begin
  foreach cert in array array[
    'CompTIA Linux+',
    'Google Professional Cloud DevOps Engineer',
    'CISSP (Certified Information Systems Security Professional)',
    'CEH (Certified Ethical Hacker)',
    'ISTQB Advanced Level Test Manager'
  ] loop
    loop
      with counts as (
        select l.letter,
               (select count(*) from public.certification_exam_question q
                 where q.certification = cert and q.correct_option = l.letter) as n
        from (values ('A'),('B'),('C'),('D')) as l(letter)
      )
      select (select letter from counts order by n desc, letter limit 1),
             (select letter from counts order by n asc, letter limit 1),
             (select max(n) - min(n) from counts)
        into over_letter, under_letter, spread;

      exit when spread <= 1;

      select min(id) into rid
        from public.certification_exam_question
       where certification = cert and correct_option = over_letter;

      exit when rid is null;

      execute format(
        'update public.certification_exam_question set %I = %I, %I = %I, correct_option = %L where id = %s',
        'option_' || lower(over_letter), 'option_' || lower(under_letter),
        'option_' || lower(under_letter), 'option_' || lower(over_letter),
        under_letter, rid);
    end loop;
  end loop;
end
$rebalance$;

-- ==================== proof: every bank has 40 ====================
do $proof$
declare
  r record;
begin
  for r in
    select c.name, coalesce(q.n, 0) as n
    from (values
      ('CompTIA Linux+'),
      ('Google Professional Cloud DevOps Engineer'),
      ('CISSP (Certified Information Systems Security Professional)'),
      ('CEH (Certified Ethical Hacker)'),
      ('ISTQB Advanced Level Test Manager')
    ) as c(name)
    left join (
      select certification, count(*) as n
      from public.certification_exam_question
      group by certification
    ) q on q.certification = c.name
  loop
    if r.n < 40 then
      raise exception 'certification bank % has only % questions on production (expected at least 40)', r.name, r.n;
    end if;
  end loop;
end
$proof$;

